cat > package.json <<'EOF'
{
  "name": "logomocja",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "bun run build.ts",
    "test": "bun test",
    "dev": "bun run build.ts && bun run serve.ts"
  }
}
EOF
cat > test/interpreter.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";

const pts = (r: { segments: any[] }) => r.segments.map((s) => [...s.from, ...s.to].map((n: number) => Math.round(n * 1e6) / 1e6));

describe("run: movement and turning", () => {
  test("a square of 100 returns to the start, drawn in order", () => {
    const r = run("powtorz 4 [np 100 pw 90]", "2d");
    expect(r.error).toBeNull();
    expect(pts(r)).toEqual([
      [0, 0, 0, 0, 100, 0],
      [0, 100, 0, 100, 100, 0],
      [100, 100, 0, 100, 0, 0],
      [100, 0, 0, 0, 0, 0],
    ]);
  });
});
EOF
bun test 2>&1 | tail -8

