cd /work/src/lang && cat > lexer.ts <<'EOF'
export type Mode = "2d" | "3d";

export interface LogoError {
  message: string;
  line: number;
  column: number;
}

export type TokKind = "num" | "word" | "var" | "color" | "badstr" | "op" | "cmp" | "[" | "]" | "(" | ")" | "," | ":" | "bad";

export interface Token {
  kind: TokKind;
  text: string;
  /** lower-cased, NFC-normalised text for words */
  norm: string;
  line: number;
  col: number;
  start: number;
  end: number;
  spaceBefore: boolean;
  spaceAfter: boolean;
  /** true when this is the first token on its line */
  first: boolean;
  /** true when this is the last token on its line */
  last: boolean;
}

export class LogoFail extends Error {
  constructor(public info: LogoError) {
    super(info.message);
  }
}

export const LIMITS = {
  chars: 50_000,
  tokens: 10_000,
  depth: 32,
  frames: 32,
  ops: 10_000,
  segments: 10_000,
  coord: 100_000,
};

const isLetter = (c: string) => /\p{L}/u.test(c);
const isWordChar = (c: string) => /[\p{L}\p{N}_]/u.test(c);
const isDigit = (c: string) => c >= "0" && c <= "9";

export function fail(message: string, t: { line: number; col: number }): never {
  throw new LogoFail({ message, line: t.line, column: t.col });
}

/** Splits source into tokens. Lexical problems become "bad"/"badstr" tokens so that the parser reports the first problem in source order. */
export function lex(source: string): Token[] {
  const toks: Token[] = [];
  let i = 0;
  let line = 1;
  let lineStart = 0;
  const n = source.length;
  const posAt = (idx: number) => ({ line, col: idx - lineStart + 1 });
  if (n > LIMITS.chars) {
    // locate the 50001st character
    let l = 1;
    let ls = 0;
    for (let k = 0; k < LIMITS.chars; k++) {
      if (source[k] === "\n") {
        l++;
        ls = k + 1;
      }
    }
    fail(`Program jest za długi: limit to ${LIMITS.chars} znaków.`, { line: l, col: LIMITS.chars - ls + 1 });
  }
  const push = (kind: TokKind, start: number, end: number) => {
    const text = source.slice(start, end);
    const p = posAt(start);
    const prev = source[start - 1];
    const next = source[end];
    const t: Token = {
      kind,
      text,
      norm: text.normalize("NFC").toLowerCase(),
      line: p.line,
      col: p.col,
      start,
      end,
      spaceBefore: start === 0 || /\s/.test(prev),
      spaceAfter: end >= n || /\s/.test(next) || next === ";",
      first: false,
      last: false,
    };
    toks.push(t);
    if (toks.length > LIMITS.tokens) fail(`Za dużo elementów programu: limit to ${LIMITS.tokens} tokenów.`, { line: t.line, col: t.col });
  };
  while (i < n) {
    const c = source[i];
    if (c === "\n") {
      line++;
      i++;
      lineStart = i;
      continue;
    }
    if (/\s/.test(c)) {
      i++;
      continue;
    }
    if (c === ";") {
      while (i < n && source[i] !== "\n") i++;
      continue;
    }
    if (isDigit(c) || (c === "." && isDigit(source[i + 1] ?? ""))) {
      const s = i;
      while (isDigit(source[i] ?? "")) i++;
      if (source[i] === "." && isDigit(source[i + 1] ?? "")) {
        i++;
        while (isDigit(source[i] ?? "")) i++;
      }
      // a number glued to letters, digits or a dot is not a number (1e3, 0x10, 1.2.3, 12.)
      if (i < n && (isWordChar(source[i]) || source[i] === ".")) {
        while (i < n && (isWordChar(source[i]) || source[i] === ".")) i++;
        push("bad", s, i);
      } else push("num", s, i);
      continue;
    }
    if (c === '"') {
      const s = i;
      i++;
      while (i < n && source[i] !== '"' && source[i] !== "\n") i++;
      if (source[i] === '"') i++;
      const text = source.slice(s, i);
      push(/^"#[0-9a-fA-F]{6}"$/.test(text) ? "color" : "badstr", s, i);
      continue;
    }
    if (c === ":" ) {
      if (isLetter(source[i + 1] ?? "") || source[i + 1] === "_") {
        const s = i;
        i++;
        while (i < n && isWordChar(source[i])) i++;
        push("var", s, i);
      } else {
        push(":", i, i + 1);
        i++;
      }
      continue;
    }
    if (isLetter(c) || c === "_") {
      const s = i;
      while (i < n && isWordChar(source[i])) i++;
      push("word", s, i);
      continue;
    }
    if (c === "<" || c === ">") {
      const two = source.slice(i, i + 2);
      if (two === "<=" || two === ">=" || two === "<>") {
        push("cmp", i, i + 2);
        i += 2;
      } else {
        push("cmp", i, i + 1);
        i++;
      }
      continue;
    }
    if (c === "=") {
      push("cmp", i, i + 1);
      i++;
      continue;
    }
    if ("+-*/".includes(c)) {
      push("op", i, i + 1);
      i++;
      continue;
    }
    if (c === "[" || c === "]" || c === "(" || c === ")" || c === ",") {
      push(c as TokKind, i, i + 1);
      i++;
      continue;
    }
    push("bad", i, i + 1);
    i++;
  }
  for (let k = 0; k < toks.length; k++) {
    toks[k].first = k === 0 || toks[k - 1].line !== toks[k].line;
    toks[k].last = k === toks.length - 1 || toks[k + 1].line !== toks[k].line;
  }
  return toks;
}
EOF
cat > ast.ts <<'EOF'
export interface Pos {
  line: number;
  col: number;
}

export type Expr =
  | { k: "num"; v: number }
  | { k: "var"; name: string }
  | { k: "rep" }
  | { k: "neg"; e: Expr }
  | { k: "bin"; op: "+" | "-" | "*" | "/"; l: Expr; r: Expr };

/** An expression together with its first token: run-time errors are reported there. */
export interface Arg {
  e: Expr;
  pos: Pos;
}

export type Stmt =
  | { k: "cmd"; name: string; arg?: Arg; pos: Pos }
  | { k: "color"; value: string; pos: Pos }
  | { k: "repeat"; count: Arg; body: Stmt[]; pos: Pos }
  | { k: "let"; name: string; arg: Arg; pos: Pos }
  | { k: "if"; cmp: string; l: Arg; r: Arg; then: Stmt[]; else?: Stmt[]; pos: Pos }
  | { k: "call"; name: string; args: Arg[]; pos: Pos };

export interface Proc {
  name: string;
  params: string[];
  body: Stmt[];
  pos: Pos;
}

export interface Program {
  main: Stmt[];
  procs: Map<string, Proc>;
}
EOF

