cat > interp.ts <<'EOF'
import type { Arg, Expr, Program, Stmt } from "./ast";
import { LogoFail, type LogoError } from "./lexer";

export type Vec = [number, number, number];
export interface Segment {
  from: Vec;
  to: Vec;
  color: string;
  width: number;
}

export interface Turtle {
  pos: Vec;
  h: Vec;
  r: Vec;
  u: Vec;
  pen: boolean;
  color: string;
  width: number;
}

export function newTurtle(): Turtle {
  return { pos: [0, 0, 0], h: [0, 1, 0], r: [1, 0, 0], u: [0, 0, 1], pen: true, color: "#16866a", width: 3 };
}

export interface Machine {
  turtle: Turtle;
  segments: Segment[];
}

export interface StepInfo {
  line: number;
  col: number;
}

const clean = (n: number) => n + 0;

export class Executor {
  machine: Machine = { turtle: newTurtle(), segments: [] };
  constructor(private program: Program) {}

  *execute(): Generator<StepInfo, void> {
    yield* this.block(this.program.main);
  }

  private *block(body: Stmt[]): Generator<StepInfo, void> {
    for (const s of body) yield* this.stmt(s);
  }

  private *stmt(s: Stmt): Generator<StepInfo, void> {
    yield { line: s.pos.line, col: s.pos.col };
    const t = this.machine.turtle;
    switch (s.k) {
      case "cmd": {
        const d = this.value(s.arg!);
        if (s.name === "fd" || s.name === "bk") this.move(s.name === "fd" ? d : -d);
        else this.turn(s.name === "rt" ? d : -d);
        return;
      }
      case "repeat": {
        const n = this.value(s.count);
        for (let k = 1; k <= n; k++) yield* this.block(s.body);
        return;
      }
    }
  }

  private value(a: Arg): number {
    return this.eval(a.e);
  }
  private eval(e: Expr): number {
    if (e.k === "num") return e.v;
    throw new LogoFail({ message: "Nieobsługiwane wyrażenie.", line: 1, column: 1 });
  }

  private move(d: number) {
    const t = this.machine.turtle;
    const to: Vec = [clean(t.pos[0] + t.h[0] * d), clean(t.pos[1] + t.h[1] * d), clean(t.pos[2] + t.h[2] * d)];
    if (t.pen && d !== 0) this.machine.segments.push({ from: t.pos, to, color: t.color, width: t.width });
    t.pos = to;
  }

  private turn(deg: number) {
    const t = this.machine.turtle;
    const [s, c] = sincos(deg);
    const h = t.h.map((v, i) => v * c + t.r[i] * s) as Vec;
    const r = t.r.map((v, i) => v * c - t.h[i] * s) as Vec;
    t.h = h;
    t.r = r;
  }
}

/** sin and cos in degrees, exact for multiples of 90. */
export function sincos(deg: number): [number, number] {
  const m = ((deg % 360) + 360) % 360;
  if (m === 0) return [0, 1];
  if (m === 90) return [1, 0];
  if (m === 180) return [0, -1];
  if (m === 270) return [-1, 0];
  const a = (deg * Math.PI) / 180;
  return [Math.sin(a), Math.cos(a)];
}

export type { LogoError };
