const len = (src: string) => {
  const r = run(src, "2d");
  return r.error ? r.error : r.segments.map((s) => s.to[1] - s.from[1]);
};

describe("run: expressions", () => {
  test("* and / bind tighter than + and -", () => expect(len("np 2 + 3 * 4")).toEqual([14]));
  test("equal precedence associates left", () => expect(len("np 20 - 5 - 3")).toEqual([12]));
  test("spacing symmetric on both sides or neither", () => {
    expect(len("np 10 - 5")).toEqual([5]);
    expect(len("np 10-5")).toEqual([5]);
  });
  test("np 10 -5 leaves a stray token reported at the minus", () => {
    const r = run("np 10 -5", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 7 });
  });
  test("stacked unary signs and parentheses", () => {
    expect(len("np -(3 - 5)")).toEqual([2]);
    expect(len("np - -2")).toEqual([2]);
    expect(len("np +(2*(1+1))")).toEqual([4]);
  });
  test("literals: .5 and 12.5", () => expect(len("np .5 np 12.5")).toEqual([0.5, 12.5]));
  test("1e3, 0x10 and NaN are errors", () => {
    expect(run("np 1e3", "2d").error).toMatchObject({ line: 1, column: 4 });
    expect(run("np 0x10", "2d").error).toMatchObject({ line: 1, column: 4 });
    expect(run("np NaN", "2d").error).toMatchObject({ line: 1, column: 4 });
  });
  test("division by zero is a run-time error at the argument's first token, keeping earlier strokes", () => {
    const r = run("np 5\nnp 3 /\n  (2 - 2)", "2d");
    expect(r.segments.length).toBe(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
});
