describe("run: pen, colour, width, home, clear", () => {
  test("defaults are #16866a, width 3; pen up draws nothing; zero moves draw nothing", () => {
    const r = run("np 0 np 10 pod np 10 opu np 5", "2d");
    expect(r.segments).toEqual([
      { from: [0, 0, 0], to: [0, 10, 0], color: "#16866a", width: 3 },
      { from: [0, 20, 0], to: [0, 25, 0], color: "#16866a", width: 3 },
    ]);
  });
  test("colour is lower-cased, width and aliases work (English, accented)", () => {
    const r = run('kolor "#C1763D" GRUBOŚĆ 7 forward 1 WIDTH 1 Naprzód 2 ws 1', "2d");
    expect(r.segments.map((s) => [s.color, s.width])).toEqual([["#c1763d", 7], ["#c1763d", 1], ["#c1763d", 1]]);
  });
  test("malformed colour is a parse error at the literal and draws nothing", () => {
    const r = run('np 5\nkolor "#12345"', "2d");
    expect(r).toEqual({ segments: [], error: expect.objectContaining({ line: 2, column: 7 }) });
  });
  test("literal width outside 1-12 or non-integer is a parse error at the argument", () => {
    expect(run("np 5 grubosc 13", "2d")).toMatchObject({ segments: [], error: { line: 1, column: 15 } });
    expect(run("np 5 grubosc 2.5", "2d").segments).toEqual([]);
  });
  test("dom draws back to the origin when the pen is down and restores orientation", () => {
    const r = run("np 10 pw 90 np 10 dom np 5", "2d");
    expect(r.segments.map((s) => [...s.from, ...s.to])).toEqual([[0, 0, 0, 0, 10, 0], [0, 10, 0, 10, 10, 0], [10, 10, 0, 0, 0, 0], [0, 0, 0, 0, 5, 0]]);
  });
  test("czyść forgets segments, later ones survive", () => {
    const r = run("np 10 czyść np 4", "2d");
    expect(r.segments.length).toBe(1);
    expect(r.segments[0].to).toEqual([0, 14, 0]);
  });
  test("stop at top level ends the program", () => {
    expect(run("np 1 powtorz 3 [np 1 stop] np 5", "2d").segments.length).toBe(2);
  });
  test("exact turns: lw/pw 90 give integer coordinates", () => {
    expect(run("lw 90 np 10", "2d").segments[0].to).toEqual([-10, 0, 0]);
  });
});

describe("run: 3D", () => {
  test("gora 90 heads along the former up (+Z); dol is the opposite", () => {
    expect(run("gora 90 np 10", "3d").segments[0].to).toEqual([0, 0, 10]);
    expect(run("dol 90 np 10", "3d").segments[0].to).toEqual([0, 0, -10]);
  });
  test("after pp 90 the up vector is the former right, so gora 90 then goes along +X", () => {
    expect(run("pp 90 gora 90 np 10", "3d").segments[0].to).toEqual([10, 0, 0]);
    expect(run("pl 90 gora 90 np 10", "3d").segments[0].to).toEqual([-10, 0, 0]);
  });
  test("pitch and roll are errors in 2D at the command, nothing drawn", () => {
    for (const c of ["gora 5", "dol 5", "pp 5", "pl 5", "pitchup 1", "rollleft 1"]) {
      expect(run("np 5\n" + c, "2d")).toMatchObject({ segments: [], error: { line: 2, column: 1 } });
    }
  });
  test("flat programs give identical coordinates in both modes", () => {
    const src = "powtorz 5 [np 100 pw 144] lw 33.3 ws 7 dom";
    expect(run(src, "3d")).toEqual(run(src, "2d"));
  });
});
