cat >> test/interpreter.test.ts <<'EOF'

describe("run: variables, nrpowt, conditionals", () => {
  test("niech assigns and reassigns; names ignore case; :name legacy form works", () => {
    expect(len("niech X 5 np :x niech x x * 2 np X")).toEqual([5, 10]);
  });
  test("nrpowt counts from 1 and refers to the innermost repeat", () => {
    expect(len("powtorz 3 [np nrpowt]")).toEqual([1, 2, 3]);
    expect(len("powtorz 2 [powtorz 3 [np nrpowt] np nrpowt * 100]")).toEqual([1, 2, 3, 100, 1, 2, 3, 200]);
    expect(len("powtorz 2 [np REPCOUNT]")).toEqual([1, 2]);
  });
  test("nrpowt outside any repeat is a parse error at the word", () => {
    expect(run("np 1\nnp nrpowt", "2d")).toMatchObject({ segments: [], error: { line: 2, column: 4 } });
  });
  test("unknown name is a parse error at the name and draws nothing", () => {
    expect(run("np 5 np bok", "2d")).toMatchObject({ segments: [], error: { line: 1, column: 9 } });
  });
  test("variable declared later at top level parses, but reading it first is a run-time error that keeps strokes", () => {
    const r = run("np 5\nnp 2 * x\nniech x 1", "2d");
    expect(r.segments.length).toBe(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("variable names may not be command words", () => {
    expect(run("niech np 5", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("jeśli runs its body only when the condition holds; all six comparisons", () => {
    expect(len("jeśli 1 < 2 [np 1] jesli 2 > 2 [np 2] IF 2 >= 2 [np 3] if 3 <= 2 [np 4] if 2 = 2 [np 5] if 2 <> 2 [np 6]")).toEqual([1, 3, 5]);
  });
  test("comparisons are exact: 0.1 + 0.2 = 0.3 is false", () => {
    expect(len("jeśli 0.1 + 0.2 = 0.3 [np 1]")).toEqual([]);
  });
  test("jeżeli picks the first or the second body", () => {
    expect(len("jeżeli 1 > 2 [np 1] [np 2] ifelse 2 > 1 [np 3] [np 4]")).toEqual([2, 3]);
  });
  test("stop inside a conditional inside a repeat ends the program", () => {
    expect(len("powtorz 5 [np nrpowt jeśli nrpowt = 2 [stop]] np 99")).toEqual([1, 2]);
  });
  test("a condition without a comparison is an error at the token found", () => {
    expect(run("jeśli 1 [np 1]", "2d").error).toMatchObject({ line: 1, column: 9 });
  });
});
EOF
