    expect(len("oto p ma: n
 niech n n + 1
 powtorz n [np 1]
już
p 2")).toEqual([1, 1, 1]);
  });
  test("nrpowt inside a procedure body not lexically in a repeat is a parse error", () => {
    const r = run("oto p
 np nrpowt
już
powtorz 2 [p]", "2d");
    expect(r).toMatchObject({ segments: [], error: { line: 2, column: 5 } });
  });
