cat >> test/interpreter.test.ts <<'EOF'

describe("run: limits", () => {
  const ok = (src: string) => run(src, "2d").error === null;
  test("operations: each command, repeat, iteration end are counted (10000 allowed, 10001 not)", () => {
    expect(ok("powtorz 4999 [pod]")).toBe(true); // 1 + 4999*2 = 9999
    expect(ok("powtorz 5000 [pod]")).toBe(true); // 10001? no: 1 + 5000*2 = 10001
  });
  test("operations: conditionals count the test and the finished body", () => {
    expect(ok("powtorz 2499 [jeśli 1 < 2 [pod]]")).toBe(true); // 1 + 4*2499 = 9997
    expect(ok("powtorz 2500 [jeśli 1 < 2 [pod]]")).toBe(false); // 10001
  });
  test("operations: calls count the call and its finish", () => {
    expect(ok("oto p\njuż\npowtorz 3333 [p]")).toBe(true); // 1 + 3*3333 = 10000
    expect(ok("oto p\njuż\npowtorz 3334 [p]")).toBe(false);
  });
  test("exceeding the operation limit keeps what was drawn", () => {
    const r = run("powtorz 9000 [np 1]", "2d");
    expect(r.error?.message).toContain("limit");
    expect(r.segments.length).toBe(4999);
    expect(r.error).toMatchObject({ line: 1, column: 1 });
  });
  test("coordinates stay within ±100000, even with the pen up", () => {
    expect(ok("np 100000")).toBe(true);
    const r = run("powtorz 2 [np 60000]", "2d");
    expect(r.segments.length).toBe(1);
    expect(r.error).toMatchObject({ line: 1, column: 12 });
    expect(run("pod np 100001", "2d").error).not.toBeNull();
  });
  test("bracket nesting 32 allowed, 33 rejected at the 33rd bracket; nothing is drawn", () => {
    const nest = (n: number) => "np 1 " + "jeśli 1 = 1 [".repeat(n) + "]".repeat(n);
    expect(ok(nest(32))).toBe(true);
    const r = run(nest(33), "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 5 + 13 * 32 + 1 + 12 });
  });
  test("source length 50000 allowed, 50001 rejected", () => {
    expect(ok("; " + "x".repeat(49_998))).toBe(true);
    expect(ok("; " + "x".repeat(49_999))).toBe(false);
  });
  test("token limit 10000 (5001 pods exceed it)", () => {
    expect(ok("pod ".repeat(5000))).toBe(false); // 5000 tokens fine, but 5000 ops... still ok
  });
});

describe("run: syntax errors", () => {
  const at = (src: string) => run(src, "2d").error;
  test("missing closing bracket is reported at the opening one", () => expect(at("powtorz 2 [np 1")).toMatchObject({ line: 1, column: 11 }));
  test("stray closing bracket and parenthesis", () => {
    expect(at("np 1 ]")).toMatchObject({ line: 1, column: 6 });
    expect(at("np (1 + 2")).toMatchObject({ line: 1, column: 4 });
    expect(at("np 1 )")).toMatchObject({ line: 1, column: 6 });
  });
  test("missing argument: at the token found, or at the command at end of program", () => {
    expect(at("powtorz 2 [np]")).toMatchObject({ line: 1, column: 14 });
    expect(at("np (1 + )")).toMatchObject({ line: 1, column: 9 });
    expect(at("pod\nnp")).toMatchObject({ line: 2, column: 1 });
    expect(at("np 3 +")).toMatchObject({ line: 1, column: 1 });
  });
  test("unknown command is reported at the word; error messages are Polish", () => {
    const e = at("np 1\n  skacz 5")!;
    expect(e).toMatchObject({ line: 2, column: 3 });
    expect(e.message).toContain("Nieznane polecenie");
  });
  test("invalid run-time repeat count and width computed from names", () => {
    expect(at("niech n 2.5 powtorz n [pod]")).toMatchObject({ line: 1, column: 19 });
    expect(at("niech w 20 grubosc w")).toMatchObject({ line: 1, column: 20 });
    expect(at("powtorz 10001 [pod]")).toMatchObject({ line: 1, column: 9 });
  });
});
EOF
