import { describe, expect, test } from "bun:test";
import { Session, type Scheduler } from "../src/session";

/** A scheduler we drive by hand: advance(ms) fires pending frame callbacks. */
function fakeScheduler() {
  let now = 0;
  let next = 1;
  const pending = new Map<number, (t: number) => void>();
  const s: Scheduler & { advance(ms: number): void; pending(): number } = {
    request(cb) {
      const id = next++;
      pending.set(id, cb);
      return id;
    },
    cancel(id) {
      pending.delete(id);
    },
    advance(ms) {
      now += ms;
      const cbs = [...pending.values()];
      pending.clear();
      cbs.forEach((cb) => cb(now));
    },
    pending: () => pending.size,
  };
  return s;
}

describe("Session: stepping and reset", () => {
  test("each step executes one command and highlights the next line", () => {
    const s = new Session(fakeScheduler());
    s.load("np 10\npw 90\nnp 20", "2d");
    expect(s.state).toBe("idle");
    s.step();
    expect(s.segments.length).toBe(1);
    expect(s.line).toBe(2);
    expect(s.state).toBe("paused");
    s.step();
    expect(s.segments.length).toBe(1);
    expect(s.line).toBe(3);
    s.step();
    expect(s.segments.map((g) => g.to)).toEqual([[0, 10, 0], [20, 10, 0]]);
    expect(s.state).toBe("finished");
    expect(s.line).toBeNull();
  });
  test("reset forgets the drawing and returns to idle; stepping starts over", () => {
    const s = new Session(fakeScheduler());
    s.load("np 10", "2d");
    s.step();
    s.reset();
    expect(s.segments).toEqual([]);
    expect(s.state).toBe("idle");
    expect(s.turtle.pos).toEqual([0, 0, 0]);
    s.step();
    expect(s.segments.length).toBe(1);
  });
  test("a parse error draws nothing and puts the session in error with the Polish message", () => {
    const s = new Session(fakeScheduler());
    s.load("np 10\nskacz", "2d");
    s.step();
    expect(s.state).toBe("error");
    expect(s.segments).toEqual([]);
    expect(s.error).toMatchObject({ line: 2, column: 1 });
  });
  test("a run-time error keeps the drawing and reports the position", () => {
    const s = new Session(fakeScheduler());
    s.load("np 10\nnp 1 / 0", "2d");
    s.step();
    s.step();
    expect(s.state).toBe("error");
    expect(s.segments.length).toBe(1);
    expect(s.error).toMatchObject({ line: 2, column: 4 });
  });
});
