cat > src/session.ts <<'EOF'
import { createExecution, LogoFail, newTurtleState, type Execution, type LogoError, type Mode, type Segment, type Turtle } from "./lang";

export interface Scheduler {
  request(cb: (now: number) => void): number;
  cancel(id: number): void;
}

export type SessionState = "idle" | "running" | "paused" | "finished" | "error";

/** Statements per second used when the speed is "instant". */
export const INSTANT = Infinity;

/**
 * Drives one program: run, step, pause, resume, reset. The UI renders from the
 * public fields and subscribes to changes; time comes from an injected scheduler.
 */
export class Session {
  state: SessionState = "idle";
  source = "";
  mode: Mode = "2d";
  error: LogoError | null = null;
  /** line of the command that will run next (1-based), or null */
  line: number | null = null;
  column: number | null = null;
  speed = 30;

  private exec: Execution | null = null;
  private primed = false;
  private frame = 0;
  private lastTime: number | null = null;
  private carry = 0;
  private listeners = new Set<() => void>();

  constructor(private scheduler: Scheduler) {}

  get segments(): Segment[] {
    return this.exec?.executor.machine.segments ?? [];
  }
  get turtle(): Turtle {
    return this.exec?.executor.machine.turtle ?? newTurtleState();
  }

  subscribe(fn: () => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
  private emit() {
    this.listeners.forEach((fn) => fn());
  }

  /** Replaces the program and forgets any execution. */
  load(source: string, mode: Mode) {
    this.stopTimer();
    this.source = source;
    this.mode = mode;
    this.clear();
    this.emit();
  }

  private clear() {
    this.exec = null;
    this.primed = false;
    this.state = "idle";
    this.error = null;
    this.line = null;
    this.column = null;
  }

  reset() {
    this.stopTimer();
    this.clear();
    this.emit();
  }

  setSpeed(statementsPerSecond: number) {
    this.speed = statementsPerSecond;
  }

  /** Starts from the beginning (when idle, finished or failed) or continues (when paused). */
  run() {
    if (this.state === "running") return;
    if (this.state !== "paused") {
      this.clear();
      if (!this.start()) return this.emit();
    }
    this.state = "running";
    this.startTimer();
    this.emit();
  }

  pause() {
    if (this.state !== "running") return;
    this.stopTimer();
    this.state = "paused";
    this.emit();
  }

  resume() {
    if (this.state === "paused") this.run();
  }

  /** Runs one command; the next one becomes the current line. */
  step() {
    if (this.state === "running") this.pause();
    if (this.state === "finished" || this.state === "error") this.clear();
    if (this.state === "idle" && !this.start()) return this.emit();
    this.advance(1);
    this.emit();
  }

  /** Runs the whole program at once, without animation. */
  runToEnd() {
    this.stopTimer();
    this.clear();
    if (this.start()) this.advance(Infinity);
    this.emit();
  }

  private start(): boolean {
    try {
      this.exec = createExecution(this.source, this.mode);
    } catch (e) {
      if (!(e instanceof LogoFail)) throw e;
      this.error = e.info;
      this.state = "error";
      return false;
    }
    this.state = "paused";
    this.primed = false;
    return true;
  }

  /** Executes up to n commands. */
  private advance(n: number) {
    const exec = this.exec!;
    try {
      if (!this.primed) {
        this.primed = true;
        this.track(exec.gen.next());
        if (this.state === "finished") return;
      }
      for (let k = 0; k < n; k++) {
        if (this.track(exec.gen.next())) return;
      }
    } catch (e) {
      if (!(e instanceof LogoFail)) throw e;
      this.stopTimer();
      this.error = e.info;
      this.state = "error";
      this.line = this.column = null;
    }
  }

  /** Records the announced next command; true when the program ended. */
  private track(r: IteratorResult<{ line: number; col: number }, void>): boolean {
    if (r.done) {
      this.stopTimer();
      this.state = "finished";
      this.line = this.column = null;
      return true;
    }
    this.line = r.value.line;
    this.column = r.value.col;
    return false;
  }

  private startTimer() {
    this.lastTime = null;
    this.carry = 0;
    this.frame = this.scheduler.request((t) => this.tick(t));
  }
  private stopTimer() {
    if (this.frame) this.scheduler.cancel(this.frame);
    this.frame = 0;
  }
  private tick(now: number) {
    this.frame = 0;
    if (this.state !== "running") return;
    const dt = this.lastTime === null ? 16 : Math.min(now - this.lastTime, 100);
    this.lastTime = now;
    this.carry += (this.speed * dt) / 1000;
    const n = Number.isFinite(this.carry) ? Math.floor(this.carry) : Infinity;
    this.carry -= Number.isFinite(n) ? n : 0;
    if (n > 0) this.advance(n);
    if (this.state === "running") this.frame = this.scheduler.request((t) => this.tick(t));
    this.emit();
  }
}
