import { describe, expect, test } from "bun:test";
import { EXAMPLES, exampleById } from "../src/examples";
import { memoryStorage } from "../src/storage";
import { Workspace } from "../src/workspace";

describe("Workspace: drafts and persistence", () => {
  test("a fresh workspace starts in 2D with the Kwadrat example and no pending load", () => {
    const w = new Workspace(memoryStorage());
    expect(w.mode).toBe("2d");
    expect(w.source).toBe(exampleById("kwadrat")!.source);
    expect(w.pending).toBeNull();
  });
  test("the draft of each mode survives a reload", () => {
    const kv = memoryStorage();
    const a = new Workspace(kv);
    a.setSource("np 77");
    a.setMode("3d");
    a.setSource("gora 10 np 5");
    const b = new Workspace(kv);
    expect(b.mode).toBe("3d");
    expect(b.source).toBe("gora 10 np 5");
    b.setMode("2d");
    expect(b.source).toBe("np 77");
  });
  test("loading an example over an untouched draft replaces it at once and switches mode", () => {
    const w = new Workspace(memoryStorage());
    expect(w.loadExample("helisa")).toBe("loaded");
    expect(w.mode).toBe("3d");
    expect(w.source).toBe(exampleById("helisa")!.source);
  });
  test("loading over a modified draft waits for confirmation and loses nothing", () => {
    const w = new Workspace(memoryStorage());
    w.setSource("np 123 ; moje");
    expect(w.loadExample("gwiazda")).toBe("needs-confirm");
    expect(w.source).toBe("np 123 ; moje");
    expect(w.pending?.label).toBe("Gwiazda");
    w.cancelLoad();
    expect(w.source).toBe("np 123 ; moje");
    expect(w.pending).toBeNull();
  });
  test("confirming replaces the draft but keeps it restorable", () => {
    const w = new Workspace(memoryStorage());
    w.setSource("np 123 ; moje");
    w.loadExample("gwiazda");
    w.confirmLoad();
    expect(w.source).toBe(exampleById("gwiazda")!.source);
    expect(w.restorable()).toBe("np 123 ; moje");
    w.restore();
    expect(w.source).toBe("np 123 ; moje");
  });
  test("a modified draft in the other mode is protected when an example needs that mode", () => {
    const w = new Workspace(memoryStorage());
    w.setMode("3d");
    w.setSource("pp 5 np 9");
    w.setMode("2d");
    expect(w.loadExample("kula")).toBe("needs-confirm");
    expect(w.mode).toBe("2d");
    w.confirmLoad();
    expect(w.mode).toBe("3d");
  });
  test("an unmodified example draft (even after reload) is not treated as unsaved work", () => {
    const kv = memoryStorage();
    const a = new Workspace(kv);
    a.loadExample("rozeta");
    const b = new Workspace(kv);
    expect(b.loadExample("drzewo")).toBe("loaded");
  });
  test("every example can be loaded by id", () => {
    for (const e of EXAMPLES) {
      const w = new Workspace(memoryStorage());
      expect(w.loadExample(e.id)).toBe("loaded");
      expect(w.mode).toBe(e.mode);
    }
  });
  test("theme choice and speed persist; corrupt storage falls back to defaults", () => {
    const kv = memoryStorage();
    const a = new Workspace(kv);
    a.setTheme("dark");
    a.setSpeedLevel(7);
    const b = new Workspace(kv);
    expect([b.theme, b.speedLevel]).toEqual(["dark", 7]);
    kv.setItem("logomocja:mode", "{{{");
    kv.setItem("logomocja:theme", "banana");
    const c = new Workspace(kv);
    expect([c.mode, c.theme]).toEqual(["2d", "auto"]);
  });
  test("storage that throws (private mode) does not break the workspace", () => {
    const broken = { getItem() { throw new Error("denied"); }, setItem() { throw new Error("denied"); }, removeItem() { throw new Error("denied"); } };
    const w = new Workspace(broken);
    w.setSource("np 1");
    expect(w.source).toBe("np 1");
  });
});
EOF
