import { describe, expect, test } from "bun:test";
import { CHALLENGES, evaluate, Progress } from "../src/challenges";
import { memoryStorage } from "../src/storage";

const ch = (id: string) => CHALLENGES.find((c) => c.id === id)!;

describe("challenges", () => {
  test("at least five, each with a task text and a mode", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    for (const c of CHALLENGES) {
      expect(c.title.length).toBeGreaterThan(2);
      expect(c.task.length).toBeGreaterThan(10);
      expect(["2d", "3d"]).toContain(c.mode);
    }
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
  });
  test("a square drawn in the opposite direction still passes (shape, not command order)", () => {
    const r = evaluate(ch("kwadrat-100"), "pw 90 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100");
    expect(r).toMatchObject({ passed: true });
  });
  test("colour and width do not matter", () => {
    expect(evaluate(ch("kwadrat-100"), 'kolor "#ff0000" grubosc 9 powtorz 4 [np 100 pw 90]').passed).toBe(true);
  });
  test("a square that is too small fails with a reason", () => {
    const r = evaluate(ch("kwadrat-100"), "powtorz 4 [np 90 pw 90]");
    expect(r.passed).toBe(false);
    expect(r.reason).toMatch(/Brakuje|zbędne|nie pokrywa/i);
  });
  test("extra strokes fail, and the reason says so", () => {
    const r = evaluate(ch("kwadrat-100"), "powtorz 4 [np 100 pw 90] np 50");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("zbędne");
  });
  test("an empty drawing and a program with an error both fail with explanations", () => {
    expect(evaluate(ch("kwadrat-100"), "pod np 100").reason).toContain("nic nie narysowano");
    const e = evaluate(ch("kwadrat-100"), "np 100 skacz");
    expect(e.passed).toBe(false);
    expect(e.reason).toContain("wiersz 1");
  });
  test("each challenge is solvable, with a check done in its own mode", () => {
    for (const c of CHALLENGES) expect([c.id, evaluate(c, c.solution).passed]).toEqual([c.id, true]);
  });
  test("a 3D challenge distinguishes planes: a flat square fails the vertical one", () => {
    const c = CHALLENGES.find((x) => x.mode === "3d")!;
    expect(evaluate(c, "powtorz 4 [np 100 pw 90]").passed).toBe(false);
  });
  test("progress persists across reloads and a later failure does not undo a pass", () => {
    const kv = memoryStorage();
    const p = new Progress(kv);
    expect(p.isSolved("kwadrat-100")).toBe(false);
    p.record("kwadrat-100", true);
    p.record("kwadrat-100", false);
    const again = new Progress(kv);
    expect(again.isSolved("kwadrat-100")).toBe(true);
    expect(again.solvedCount()).toBe(1);
  });
});
