import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";
import { memoryStorage } from "../src/storage";
import { Studio } from "../src/studio";
import type { Scheduler } from "../src/session";

const idle: Scheduler = { request: () => 1, cancel: () => {} };
const make = () => new Studio(memoryStorage(), idle);

describe("Studio: the open/run hook contract", () => {
  test("api exposes version, run and open", () => {
    const api = make().api();
    expect(typeof api.version).toBe("string");
    expect(typeof api.run).toBe("function");
    expect(typeof api.open).toBe("function");
  });
  test("api.run is the pure interpreter and does not touch the editor", async () => {
    const s = make();
    const before = s.workspace.source;
    const r = await s.api().run("np 5 pw 90 np 5", "2d");
    expect(r).toEqual(run("np 5 pw 90 np 5", "2d"));
    expect(s.workspace.source).toBe(before);
  });
  test("api.open loads into the editor in that mode, runs to the end and returns the result", async () => {
    const s = make();
    const r = await s.api().open("gora 90 np 10", "3d");
    expect(r.error).toBeNull();
    expect(r.segments[0].to).toEqual([0, 0, 10]);
    expect(s.workspace.mode).toBe("3d");
    expect(s.workspace.source).toBe("gora 90 np 10");
    expect(s.session.state).toBe("finished");
    expect(s.session.segments).toEqual(r.segments);
    expect(s.fitRequests).toBeGreaterThan(0);
  });
  test("open never asks for confirmation, even over a modified draft, and can be repeated", async () => {
    const s = make();
    s.edit("np 999 ; moje");
    await s.api().open("np 1", "2d");
    const r = await s.api().open("np 2", "2d");
    expect(s.workspace.pending).toBeNull();
    expect(r.segments.length).toBe(1);
    expect(s.workspace.source).toBe("np 2");
  });
  test("open with a parse error draws nothing but shows the error", async () => {
    const s = make();
    const r = await s.api().open("np 1\nskacz", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 1 });
    expect(s.session.error).toMatchObject({ line: 2 });
  });
  test("reset after open clears the drawing; running again repeats it identically", async () => {
    const s = make();
    const first = await s.api().open("powtorz 3 [np 10 pw 120]", "2d");
    s.reset();
    expect(s.session.segments).toEqual([]);
    s.session.runToEnd();
    expect(s.session.segments).toEqual(first.segments);
  });
  test("permalinks load and run at once; a bad link is reported without touching the draft", () => {
    const s = make();
    s.edit("np 5 ; moje");
    const { encodePermalink } = require("../src/share");
    const hash = encodePermalink("", "powtorz 4 [np 20 pw 90]", "2d").split("#")[1];
    expect(s.openHash("#" + hash)).toBe("opened");
    expect(s.session.segments.length).toBe(4);
    expect(s.workspace.restorable()).toBe("np 5 ; moje");
    expect(s.openHash("#/u/9d/xx")).toBe("ignored");
    expect(s.workspace.source).toBe("powtorz 4 [np 20 pw 90]");
  });
});

describe("Studio: editing while a program runs", () => {
  test("editing is refused while running, resets a paused run, and leaves a finished drawing in place", () => {
    const frames: Array<(t: number) => void> = [];
    const sch: Scheduler = { request: (cb) => (frames.push(cb), frames.length), cancel: () => {} };
    const s = new Studio(memoryStorage(), sch);
    s.edit("powtorz 50 [np 1]");
    s.run();
    expect(s.session.state).toBe("running");
    expect(s.edit("np 2")).toBe(false);
    expect(s.workspace.source).toBe("powtorz 50 [np 1]");
    s.pause();
    expect(s.edit("np 3")).toBe(true);
    expect(s.session.state).toBe("idle");
    s.session.runToEnd();
    expect(s.edit("np 4")).toBe(true);
    expect(s.session.segments.length).toBe(1);
    expect(s.stale).toBe(true);
  });
  test("a syntax error is shown while typing, without running anything", () => {
    const s = make();
    s.edit("np 1\nnp (");
    expect(s.liveError).toMatchObject({ line: 2 });
    s.edit("np 1");
    expect(s.liveError).toBeNull();
  });
});
