import type { Mode } from "./lang";

const toB64Url = (text: string): string => {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};

const fromB64Url = (s: string): string | null => {
  if (!/^[A-Za-z0-9_-]*$/.test(s) || s.length % 4 === 1) return null;
  try {
    const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
};

/** Permalink = page URL plus a hash route `#/u/<mode>/<program>`; hash routing needs no server rewrites. */
export function encodePermalink(base: string, source: string, mode: Mode): string {
  const page = base.split("#")[0];
  return `${page}#/u/${mode}/${toB64Url(source)}`;
}

export function decodePermalink(hash: string): { source: string; mode: Mode } | null {
  const m = /^#?\/u\/(2d|3d)\/([^/]*)$/.exec(hash);
  if (!m) return null;
  const source = fromB64Url(m[2]);
  return source === null ? null : { source, mode: m[1] as Mode };
}

export function parseLogoFile(text: string): string {
  return text.replace(/^﻿/, "").replace(/\r\n?/g, "\n");
}

export const logoFileName = (mode: Mode) => `program-${mode}.logo`;
