import { run, type Mode, type Segment } from "./lang";
import { safe, type KV } from "./storage";

export interface Challenge {
  id: string;
  title: string;
  mode: Mode;
  /** what to draw, in Polish */
  task: string;
  hint: string;
  /** a reference program; the expected drawing is whatever it draws */
  solution: string;
}

export const CHALLENGES: Challenge[] = [
  {
    id: "kwadrat-100",
    title: "Kwadrat o boku 100",
    mode: "2d",
    task: "Narysuj kwadrat o boku 100. Jeden jego wierzchołek ma leżeć w środku układu (0, 0), a kwadrat ma sięgać w prawo i w górę.",
    hint: "Cztery razy to samo: krok naprzód i skręt o 90°. Użyj powtórz.",
    solution: "powtorz 4 [np 100 pw 90]",
  },
  {
    id: "trojkat-120",
    title: "Trójkąt równoboczny",
    mode: "2d",
    task: "Narysuj trójkąt równoboczny o boku 120. Pierwszy bok ma iść od środka (0, 0) prosto w górę, a trójkąt ma leżeć po prawej stronie.",
    hint: "Kąt skrętu to nie kąt trójkąta! Żółw obraca się o 360° / 3.",
    solution: "powtorz 3 [np 120 pw 120]",
  },
  {
    id: "szesciokat-70",
    title: "Sześciokąt foremny",
    mode: "2d",
    task: "Narysuj sześciokąt foremny o boku 70, zaczynając od środka (0, 0) w górę i skręcając w prawo.",
    hint: "Sześć boków, skręt o 60° po każdym.",
    solution: "powtorz 6 [np 70 pw 60]",
  },
  {
    id: "krzyz-80",
    title: "Krzyż",
    mode: "2d",
    task: "Narysuj krzyż: cztery ramiona długości 80, wychodzące ze środka (0, 0) w górę, w prawo, w dół i w lewo.",
    hint: "Każde ramię to krok naprzód i krok wstecz. Potem skręt o 90°.",
    solution: "powtorz 4 [np 80 ws 80 pw 90]",
  },
  {
    id: "schodki-5",
    title: "Schodki",
    mode: "2d",
    task: "Narysuj pięć schodków. Każdy stopień to 30 w górę i 30 w prawo; pierwszy zaczyna się w środku (0, 0).",
    hint: "Jeden stopień: np 30, pw 90, np 30, lw 90. Powtórz pięć razy.",
    solution: "powtorz 5 [np 30 pw 90 np 30 lw 90]",
  },
  {
    id: "gwiazda-150",
    title: "Pięcioramienna gwiazda",
    mode: "2d",
    task: "Narysuj gwiazdę pięcioramienną jednym pociągnięciem, każdy odcinek ma długość 150. Zacznij od środka (0, 0) w górę.",
    hint: "Kąt skrętu to 144°.",
    solution: "powtorz 5 [np 150 pw 144]",
  },
  {
    id: "kwadrat-pionowy",
    title: "Kwadrat stojący",
    mode: "3d",
    task: "W trybie 3D narysuj kwadrat o boku 100 stojący pionowo, w płaszczyźnie XZ: jeden wierzchołek w (0, 0, 0), reszta wzdłuż osi X i Z.",
    hint: "Zacznij od podniesienia dziobu: gora 90. Potem zwykły kwadrat.",
    solution: "gora 90 powtorz 4 [np 100 pw 90]",
  },
];

export interface Verdict {
  passed: boolean;
  reason: string;
}

const STEP = 2;
const TOLERANCE = 2.5;
const ALLOWED_MISS = 0.02;
const MAX_SEGMENTS = 5000;

type V = [number, number, number];

function distToSegment(p: V, a: V, b: V): number {
  const ab: V = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const ap: V = [p[0] - a[0], p[1] - a[1], p[2] - a[2]];
  const l2 = ab[0] ** 2 + ab[1] ** 2 + ab[2] ** 2;
  let t = l2 === 0 ? 0 : (ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(ap[0] - ab[0] * t, ap[1] - ab[1] * t, ap[2] - ab[2] * t);
}

function samples(segs: Segment[]): V[] {
  const out: V[] = [];
  for (const s of segs) {
    const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.min(40, Math.max(1, Math.ceil(len / STEP)));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      out.push([s.from[0] + (s.to[0] - s.from[0]) * t, s.from[1] + (s.to[1] - s.from[1]) * t, s.from[2] + (s.to[2] - s.from[2]) * t]);
    }
  }
  return out;
}

/** Share of points of `a` that lie farther than the tolerance from every segment of `b`, plus one such point. */
function uncovered(a: Segment[], b: Segment[]): { share: number; example: V | null } {
  const pts = samples(a);
  let bad = 0;
  let example: V | null = null;
  for (const p of pts) {
    let near = false;
    for (const s of b) {
      if (distToSegment(p, s.from, s.to) <= TOLERANCE) {
        near = true;
        break;
      }
    }
    if (!near) {
      bad++;
      example ??= p;
    }
  }
  return { share: pts.length ? bad / pts.length : 0, example };
}

const fmt = (p: V, mode: Mode) => (mode === "2d" ? `(${Math.round(p[0])}, ${Math.round(p[1])})` : `(${Math.round(p[0])}, ${Math.round(p[1])}, ${Math.round(p[2])})`);

export function expectedDrawing(c: Challenge): Segment[] {
  return run(c.solution, c.mode).segments;
}

/** Compares the shape the user's program draws with the expected one: where lines lie, not how they were drawn. */
export function evaluate(c: Challenge, source: string): Verdict {
  const got = run(source, c.mode);
  if (got.error) {
    return { passed: false, reason: `Program zawiera błąd (wiersz ${got.error.line}, kolumna ${got.error.column}): ${got.error.message}` };
  }
  if (got.segments.length === 0) return { passed: false, reason: "Program działa, ale nic nie narysowano. Czy pióro jest opuszczone?" };
  if (got.segments.length > MAX_SEGMENTS) return { passed: false, reason: "Rysunek ma za dużo odcinków, żeby go porównać." };
  const want = expectedDrawing(c);
  const missing = uncovered(want, got.segments);
  const extra = uncovered(got.segments, want);
  if (missing.share > ALLOWED_MISS) {
    return {
      passed: false,
      reason: `Brakuje części rysunku, na przykład w okolicy ${fmt(missing.example!, c.mode)}. Sprawdź długości boków i kierunki skrętów.`,
    };
  }
  if (extra.share > ALLOWED_MISS) {
    return { passed: false, reason: `Na rysunku są zbędne linie, na przykład w okolicy ${fmt(extra.example!, c.mode)}.` };
  }
  return { passed: true, reason: "Zgadza się! Rysunek pokrywa się ze wzorem." };
}

const KEY = "logomocja:challenges";

/** Which challenges were solved, persisted locally. A pass is never undone by a later failure. */
export class Progress {
  private solved: Record<string, number> = {};
  private kv: KV;
  constructor(kv: KV) {
    this.kv = safe(kv);
    try {
      const v = JSON.parse(this.kv.getItem(KEY) ?? "{}");
      if (v && typeof v === "object") this.solved = v;
    } catch {
      /* corrupt: start over */
    }
  }
  isSolved(id: string) {
    return id in this.solved;
  }
  solvedCount() {
    return CHALLENGES.filter((c) => this.isSolved(c.id)).length;
  }
  record(id: string, passed: boolean) {
    if (!passed || this.isSolved(id)) return;
    this.solved[id] = Date.now();
    this.kv.setItem(KEY, JSON.stringify(this.solved));
  }
}
