      const t = i / n;
      out.push([s.from[0] + (s.to[0] - s.from[0]) * t, s.from[1] + (s.to[1] - s.from[1]) * t, s.from[2] + (s.to[2] - s.from[2]) * t]);
    }
  }
  return out;
}

/** Share of points of `a` that lie farther than the tolerance from every segment of `b`, plus one such point. */
function uncovered(a: Segment[], b: Segment[]): { share: number; example: V | null } {
  const pts = samples(a);
  let bad = 0;
  let example: V | null = null;
  for (const p of pts) {
    let near = false;
    for (const s of b) {
      if (distToSegment(p, s.from, s.to) <= TOLERANCE) {
        near = true;
        break;
      }
    }
    if (!near) {
      bad++;
      example ??= p;
    }
  }
  return { share: pts.length ? bad / pts.length : 0, example };
}

const fmt = (p: V, mode: Mode) => (mode === "2d" ? `(${Math.round(p[0])}, ${Math.round(p[1])})` : `(${Math.round(p[0])}, ${Math.round(p[1])}, ${Math.round(p[2])})`);

export function expectedDrawing(c: Challenge): Segment[] {
  return run(c.solution, c.mode).segments;
}

/** Compares the shape the user's program draws with the expected one: where lines lie, not how they were drawn. */
export function evaluate(c: Challenge, source: string): Verdict {
  const got = run(source, c.mode);
  if (got.error) {
    return { passed: false, reason: `Program zawiera błąd (wiersz ${got.error.line}, kolumna ${got.error.column}): ${got.error.message}` };
  }
  if (got.segments.length === 0) return { passed: false, reason: "Program działa, ale nic nie narysowano. Czy pióro jest opuszczone?" };
  if (got.segments.length > MAX_SEGMENTS) return { passed: false, reason: "Rysunek ma za dużo odcinków, żeby go porównać." };
  const want = expectedDrawing(c);
  const missing = uncovered(want, got.segments);
  const extra = uncovered(got.segments, want);
  if (missing.share > ALLOWED_MISS) {
    return {
      passed: false,
      reason: `Brakuje części rysunku, na przykład w okolicy ${fmt(missing.example!, c.mode)}. Sprawdź długości boków i kierunki skrętów.`,
    };
  }
  if (extra.share > ALLOWED_MISS) {
    return { passed: false, reason: `Na rysunku są zbędne linie, na przykład w okolicy ${fmt(extra.example!, c.mode)}.` };
  }
  return { passed: true, reason: "Zgadza się! Rysunek pokrywa się ze wzorem." };
}

const KEY = "logomocja:challenges";

/** Which challenges were solved, persisted locally. A pass is never undone by a later failure. */
export class Progress {
  private solved: Record<string, number> = {};
  private kv: KV;
  constructor(kv: KV) {
    this.kv = safe(kv);
    try {
      const v = JSON.parse(this.kv.getItem(KEY) ?? "{}");
      if (v && typeof v === "object") this.solved = v;
    } catch {
      /* corrupt: start over */
    }
  }
  isSolved(id: string) {
    return id in this.solved;
  }
  solvedCount() {
    return CHALLENGES.filter((c) => this.isSolved(c.id)).length;
  }
  record(id: string, passed: boolean) {
    if (!passed || this.isSolved(id)) return;
    this.solved[id] = Date.now();
    this.kv.setItem(KEY, JSON.stringify(this.solved));
  }
}
EOF
