import { Progress } from "./challenges";
import { check, run, type LogoError, type Mode, type RunResult } from "./lang";
import { Session, type Scheduler } from "./session";
import { decodePermalink } from "./share";
import type { KV } from "./storage";
import { Workspace, type LoadRequest } from "./workspace";

export const VERSION = "1.0.0";

export interface LogomocjaApi {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

/** Everything the interface does, without the DOM: the UI only renders it and forwards events. */
export class Studio {
  readonly workspace: Workspace;
  readonly session: Session;
  readonly progress: Progress;
  /** how many times the views were asked to fit the drawing */
  fitRequests = 0;
  /** the drawing no longer matches the editor text */
  stale = false;
  /** parse error of the current text, shown while typing */
  liveError: LogoError | null = null;
  private listeners = new Set<() => void>();

  constructor(kv: KV, scheduler: Scheduler) {
    this.workspace = new Workspace(kv);
    this.session = new Session(scheduler);
    this.progress = new Progress(kv);
    this.session.subscribe(() => this.emit());
    this.updateLive();
  }

  subscribe(fn: () => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
  emit() {
    this.listeners.forEach((fn) => fn());
  }

  private updateLive() {
    const src = this.workspace.source;
    this.liveError = src.trim() ? check(src, this.workspace.mode) : null;
  }

  /** The user edited the text. Refused while the animation runs. */
  edit(text: string): boolean {
    if (this.session.state === "running") return false;
    this.workspace.setSource(text);
    if (this.session.state === "paused") this.session.reset();
    else if (this.session.state === "finished" || this.session.state === "error") this.stale = true;
    this.updateLive();
    this.emit();
    return true;
  }

  setMode(mode: Mode) {
    if (mode === this.workspace.mode) return;
    this.session.reset();
    this.workspace.setMode(mode);
    this.stale = false;
    this.updateLive();
    this.fitRequests++;
    this.emit();
  }

  private prepare() {
    const s = this.session.state;
    if (s === "idle" || s === "finished" || s === "error") this.session.load(this.workspace.source, this.workspace.mode);
    this.stale = false;
  }

  run() {
    if (this.session.state === "paused") return this.session.run();
    this.prepare();
    this.session.run();
  }
  step() {
    this.prepare();
    this.session.step();
  }
  pause() {
    this.session.pause();
  }
  resume() {
    this.session.resume();
  }
  togglePause() {
    if (this.session.state === "running") this.pause();
    else if (this.session.state === "paused") this.resume();
  }
  reset() {
    this.session.reset();
    this.stale = false;
    this.fitRequests++;
    this.emit();
  }

  /** Runs the current text at once and asks the views to fit it. */
  runInstantly(): RunResult {
    this.session.load(this.workspace.source, this.workspace.mode);
    this.session.runToEnd();
    this.stale = false;
    this.updateLive();
    this.fitRequests++;
    this.emit();
    return { segments: this.session.segments, error: this.session.error };
  }

  loadExample(id: string): "loaded" | "needs-confirm" {
    return this.afterRequest(this.workspace.loadExample(id));
  }
  requestLoad(req: LoadRequest) {
    return this.afterRequest(this.workspace.requestLoad(req));
  }
  confirmLoad() {
    this.workspace.confirmLoad();
    this.runInstantly();
  }
  cancelLoad() {
    this.workspace.cancelLoad();
    this.emit();
  }
  restore() {
    this.workspace.restore();
    this.runInstantly();
  }
  private afterRequest(r: "loaded" | "needs-confirm") {
    if (r === "loaded") this.runInstantly();
    else this.emit();
    return r;
  }

  /** Opens a permalink hash: loads and runs it. */
  openHash(hash: string): "opened" | "ignored" {
    const link = decodePermalink(hash);
    if (!link) return "ignored";
    this.workspace.forceLoad({ ...link, label: "Link" });
    this.runInstantly();
    return "opened";
  }

  api(): LogomocjaApi {
    return {
      version: VERSION,
      run: (source, mode) => run(source, mode),
      open: async (source, mode) => {
        this.workspace.forceLoad({ source, mode, label: "open" });
        return this.runInstantly();
      },
    };
  }
}
