cat > resolve.py <<'EOF'
import re,sys,subprocess,os
pk={}
cur={}
for block in open('/tmp/debtool/Packages',encoding='utf8').read().split('\n\n'):
    d={}
    for m in re.finditer(r'^([A-Za-z-]+): (.*)$',block,re.M): d[m.group(1)]=m.group(2)
    if 'Package' in d: pk[d['Package']]=d
prov={}
for n,d in pk.items():
    for p in d.get('Provides','').split(','):
        p=p.strip().split(' ')[0]
        if p: prov.setdefault(p,n)
# installed
inst=set(subprocess.run(['dpkg-query','-W','-f','${Package}\n'],capture_output=True,text=True).stdout.split())
want=sys.argv[1:]
seen=set();order=[]
def visit(n):
    if n in seen: return
    seen.add(n)
    if n in inst: return
    d=pk.get(n) or pk.get(prov.get(n,''))
    if not d: print('missing',n,file=sys.stderr);return
    order.append(d['Filename'])
    for dep in d.get('Depends','').split(','):
        alt=dep.strip().split('|')[0].strip().split(' ')[0].split(':')[0]
        if alt: visit(alt)
for w in want: visit(w)
print('\n'.join(order))
EOF
