cat > build.ts <<'EOF'
// Static build: bundles src/main.ts and copies index.html + style.css into dist/.
// Asset URLs are relative, so the site works from any sub-path (BASE_PATH) with no rewrites;
// routing uses the URL hash, so a refresh on any route needs no server support.
import { cp, mkdir, readFile, rm, writeFile } from "node:fs/promises";

const raw = process.env.BASE_PATH ?? "/";
const base = (raw.startsWith("/") ? raw : "/" + raw).replace(/\/*$/, "/");

await rm("dist", { recursive: true, force: true });
await mkdir("dist/assets", { recursive: true });

const result = await Bun.build({
  entrypoints: ["src/main.ts"],
  outdir: "dist/assets",
  naming: "app.[hash].js",
  minify: true,
  target: "browser",
});
if (!result.success) {
  for (const log of result.logs) console.error(log);
  process.exit(1);
}
const js = result.outputs.find((o) => o.path.endsWith(".js"))!.path.split("/").pop()!;

const css = await readFile("src/style.css", "utf8");
const cssName = `style.${new Bun.CryptoHasher("sha1").update(css).digest("hex").slice(0, 8)}.css`;
await writeFile(`dist/assets/${cssName}`, css);

let html = await readFile("index.html", "utf8");
html = html.replace("%CSS%", `./assets/${cssName}`).replace("%JS%", `./assets/${js}`).replace("%BASE%", base);
await writeFile("dist/index.html", html);
await cp("public", "dist", { recursive: true });
console.log(`dist/ ready (BASE_PATH=${base}): ${js}, ${cssName}`);
EOF
