import { KEYWORDS } from "../lang";
import { escapeHtml } from "./dom";

export interface ErrorMark {
  line: number;
  column: number;
}

const TOKEN =
  /(;.*$)|("[^"\n]*"?)|(\d+(?:\.\d+)?|\.\d+)|(:?[\p{L}_][\p{L}\p{N}_]*)|(\[|\]|\(|\))|(<=|>=|<>|[<>=+\-*/,])|(\s+)|(.)/gu;

/** One HTML string per source line; the error token (if any) is wrapped in .err. */
export function highlightLines(source: string, error: ErrorMark | null = null): string[] {
  return source.split("\n").map((line, i) => {
    const errCol = error && error.line === i + 1 ? error.column - 1 : -1;
    let html = "";
    let pos = 0;
    let errEnd = -1;
    if (errCol >= 0) {
      const m = /^(?:"[^"\n]*"?|[\p{L}\p{N}_:.]+|\S)/u.exec(line.slice(errCol));
      errEnd = errCol + (m ? m[0].length : 1);
    }
    for (const m of line.matchAll(TOKEN)) {
      const [text, comment, str, num, word, bracket, op, space] = m;
      const start = m.index ?? pos;
      pos = start + text.length;
      let cls = "";
      let style = "";
      if (comment) cls = "t-com";
      else if (str) {
        cls = "t-str";
        if (/^"#[0-9a-fA-F]{6}"$/.test(str)) style = ` style="--sw:${str.slice(1, -1)}"`;
      } else if (num) cls = "t-num";
      else if (word) {
        const w = word.normalize("NFC").toLowerCase();
        cls = w === "nrpowt" || w === "repcount" ? "t-rep" : word[0] === ":" ? "t-name" : KEYWORDS.has(w) ? "t-kw" : "t-name";
      } else if (bracket) cls = "t-br";
      else if (op) cls = "t-op";
      else if (space) {
        html += escapeHtml(text);
        continue;
      }
      const inErr = errCol >= 0 && start >= errCol && start < errEnd;
      html += `<span class="${cls}${inErr ? " err" : ""}"${style}>${escapeHtml(text)}</span>`;
    }
    return html || "​";
  });
}
