import { h } from "./dom";
import { highlightLines, type ErrorMark } from "./highlight";

/** Textarea with a highlighted overlay and a line-number gutter, all inside one scroller. */
export class Editor {
  readonly el: HTMLElement;
  private scroller: HTMLElement;
  private gutter: HTMLElement;
  private overlay: HTMLElement;
  private area: HTMLTextAreaElement;
  private error: ErrorMark | null = null;
  private execLine: number | null = null;
  private lineCount = 0;
  onInput: (text: string) => void = () => {};

  constructor() {
    this.gutter = h("div", { class: "gutter", "aria-hidden": "true" });
    this.overlay = h("div", { class: "overlay", "aria-hidden": "true" });
    this.area = h("textarea", {
      class: "input",
      spellcheck: "false",
      autocapitalize: "off",
      autocomplete: "off",
      autocorrect: "off",
      wrap: "off",
      "aria-label": "Kod programu Logo",
      "aria-describedby": "status",
    });
    this.area.addEventListener("input", () => {
      this.render();
      this.onInput(this.area.value);
    });
    const code = h("div", { class: "code" }, this.overlay, this.area);
    this.scroller = h("div", { class: "scroller" }, this.gutter, code);
    this.el = h("div", { class: "editor" }, this.scroller);
    // clicking the empty area below the text focuses the editor
    this.scroller.addEventListener("pointerdown", (e) => {
      if (e.target === this.scroller || e.target === code) setTimeout(() => this.area.focus());
    });
  }

  get value() {
    return this.area.value;
  }

  setValue(text: string) {
    if (this.area.value === text) return;
    this.area.value = text;
    this.render();
  }

  setReadonly(on: boolean) {
    this.area.readOnly = on;
    this.el.classList.toggle("locked", on);
  }

  setError(e: ErrorMark | null) {
    if (this.error?.line === e?.line && this.error?.column === e?.column) return;
    this.error = e;
    this.render();
  }

  setExecLine(line: number | null) {
    if (this.execLine === line) return;
    this.execLine = line;
    this.paintLineStates();
    if (line !== null) this.overlay.children[line - 1]?.scrollIntoView({ block: "nearest" });
  }

  focus(at?: { line: number; column: number }) {
    this.area.focus();
    if (at) {
      const lines = this.area.value.split("\n");
      let off = 0;
      for (let i = 0; i < at.line - 1 && i < lines.length; i++) off += lines[i].length + 1;
      off += Math.min(at.column - 1, lines[at.line - 1]?.length ?? 0);
      this.area.setSelectionRange(off, off);
      this.overlay.children[at.line - 1]?.scrollIntoView({ block: "center" });
    }
  }

  private render() {
    const text = this.area.value;
    const lines = highlightLines(text, this.error);
    if (lines.length !== this.lineCount) {
      this.lineCount = lines.length;
      this.gutter.replaceChildren(...lines.map((_, i) => h("div", { class: "ln" }, String(i + 1))));
    }
    this.overlay.replaceChildren(
      ...lines.map((html) => {
        const d = document.createElement("div");
        d.className = "l";
        d.innerHTML = html;
        return d;
      }),
    );
    const longest = text.split("\n").reduce((m, l) => Math.max(m, l.length), 0);
    this.area.style.minWidth = `calc(${longest + 2}ch + 1.5rem)`;
    this.area.style.height = "0px";
    this.area.style.height = `${Math.max(this.area.scrollHeight, 40)}px`;
    this.paintLineStates();
  }

  private paintLineStates() {
    for (let i = 0; i < this.lineCount; i++) {
      const n = i + 1;
      this.overlay.children[i]?.classList.toggle("exec", n === this.execLine);
      this.overlay.children[i]?.classList.toggle("bad", n === this.error?.line);
      this.gutter.children[i]?.classList.toggle("exec", n === this.execLine);
      this.gutter.children[i]?.classList.toggle("bad", n === this.error?.line);
    }
  }
}
