import type { Segment, Turtle } from "../lang";

export interface Scene {
  segments: Segment[];
  turtle: Turtle;
  /** expected drawing of the active challenge */
  ghost: Segment[];
}

export interface DrawingView {
  readonly el: HTMLElement;
  setScene(scene: Scene): void;
  fit(): void;
  zoomBy(factor: number): void;
  /** back to the default camera (3D) or the fitted view (2D) */
  resetView(): void;
  toPng(): Promise<Blob | null>;
  themeChanged(): void;
  /** the view became visible or changed size */
  resize(): void;
}

export interface Palette {
  paper: string;
  grid: string;
  gridStrong: string;
  axis: string;
  axisX: string;
  axisY: string;
  axisZ: string;
  ink: string;
  muted: string;
  ghost: string;
  marker: string;
  up: string;
}

export function readPalette(): Palette {
  const cs = getComputedStyle(document.documentElement);
  const g = (n: string) => cs.getPropertyValue(n).trim();
  return {
    paper: g("--paper"),
    grid: g("--paper-grid"),
    gridStrong: g("--paper-grid-strong"),
    axis: g("--paper-axis"),
    axisX: g("--axis-x"),
    axisY: g("--axis-y"),
    axisZ: g("--axis-z"),
    ink: g("--paper-ink"),
    muted: g("--paper-muted"),
    ghost: g("--ghost"),
    marker: g("--marker"),
    up: g("--marker-up"),
  };
}

export function niceStep(raw: number): number {
  const p = Math.pow(10, Math.floor(Math.log10(raw)));
  const n = raw / p;
  return (n < 1.5 ? 1 : n < 3.5 ? 2 : n < 7.5 ? 5 : 10) * p;
}

export function bounds(scene: Scene, extra: Array<[number, number, number]> = [[0, 0, 0]]) {
  let minX = Infinity, minY = Infinity, minZ = Infinity, maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
  const add = (p: [number, number, number]) => {
    minX = Math.min(minX, p[0]); maxX = Math.max(maxX, p[0]);
