      ctx.stroke();
    }
    let color = "", width = 0, px = NaN, py = NaN, open = false;
    for (const s of scene.segments) {
      const fx = X(s.from[0]), fy = Y(s.from[1]);
      if (!open || s.color !== color || s.width !== width || fx !== px || fy !== py) {
        if (open) ctx.stroke();
        ctx.beginPath();
        ctx.strokeStyle = color = s.color;
        ctx.lineWidth = width = s.width;
        ctx.moveTo(fx, fy);
        open = true;
      }
      px = X(s.to[0]);
      py = Y(s.to[1]);
      ctx.lineTo(px, py);
    }
    if (open) ctx.stroke();
    if (chrome) this.drawTurtle(ctx, scene, X, Y);
  }

  private drawGrid(ctx: CanvasRenderingContext2D, w: number, hgt: number, X: (x: number) => number, Y: (y: number) => number, scale: number, cx: number, cy: number) {
    const p = this.pal;
    const step = niceStep(56 / scale);
    const x0 = cx - w / 2 / scale, x1 = cx + w / 2 / scale;
    const y0 = cy - hgt / 2 / scale, y1 = cy + hgt / 2 / scale;
    ctx.lineWidth = 1;
    ctx.strokeStyle = p.grid;
    ctx.beginPath();
    for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) {
      const sx = Math.round(X(x)) + 0.5;
      ctx.moveTo(sx, 0);
      ctx.lineTo(sx, hgt);
    }
    for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) {
      const sy = Math.round(Y(y)) + 0.5;
      ctx.moveTo(0, sy);
      ctx.lineTo(w, sy);
    }
    ctx.stroke();
    // axes through the origin, with tick labels
    const ox = X(0), oy = Y(0);
    ctx.strokeStyle = p.axis;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(ox, 0);
    ctx.lineTo(ox, hgt);
    ctx.moveTo(0, oy);
    ctx.lineTo(w, oy);
    ctx.stroke();
    ctx.fillStyle = p.muted;
    ctx.font = "11px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";
    ctx.textBaseline = "top";
    ctx.textAlign = "center";
    const labelY = Math.min(Math.max(oy + 4, 2), hgt - 14);
    for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) {
      if (Math.abs(x) < step / 2) continue;
      ctx.fillText(fmt(x), X(x), labelY);
    }
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    const labelX = Math.min(Math.max(ox + 5, 2), w - 40);
    for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) {
      if (Math.abs(y) < step / 2) continue;
      ctx.fillText(fmt(y), labelX, Y(y) - 8);
    }
    // origin marker and axis names
    ctx.fillStyle = p.axis;
    ctx.beginPath();
    ctx.arc(ox, oy, 3.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = p.muted;
    ctx.font = "600 12px system-ui, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText("0", ox + 7, oy + 6);
    ctx.fillText("X", Math.min(w - 14, w - 14), Math.min(Math.max(oy - 18, 2), hgt - 20));
    ctx.fillText("Y", Math.min(Math.max(ox + 8, 2), w - 14), 4);
  }

  private drawTurtle(ctx: CanvasRenderingContext2D, scene: Scene, X: (x: number) => number, Y: (y: number) => number) {
    const t = scene.turtle;
    const x = X(t.pos[0]), y = Y(t.pos[1]);
    const dx = t.h[0], dy = -t.h[1];
    const len = Math.hypot(dx, dy) || 1;
    const ux = dx / len, uy = dy / len;
    const nx = -uy, ny = ux;
    const s = 11;
    ctx.beginPath();
    ctx.moveTo(x + ux * s * 1.3, y + uy * s * 1.3);
    ctx.lineTo(x - ux * s * 0.8 + nx * s * 0.8, y - uy * s * 0.8 + ny * s * 0.8);
    ctx.lineTo(x - ux * s * 0.4, y - uy * s * 0.4);
    ctx.lineTo(x - ux * s * 0.8 - nx * s * 0.8, y - uy * s * 0.8 - ny * s * 0.8);
    ctx.closePath();
    ctx.fillStyle = t.pen ? this.pal.marker : this.pal.paper;
    ctx.strokeStyle = this.pal.ink;
    ctx.lineWidth = 1.75;
    ctx.lineJoin = "round";
    ctx.fill();
    ctx.stroke();
  }

  toPng(): Promise<Blob | null> {
    const scene = this.scene;
    const out = document.createElement("canvas");
    const W = 1600;
    let H = 1200;
    let cx = 0, cy = 0, scale = 1;
    if (scene) {
      const b = bounds(scene, [[0, 0, 0]]);
      const bw = Math.max(b.maxX - b.minX, 40), bh = Math.max(b.maxY - b.minY, 40);
      const pad = 80;
      scale = Math.min((W - pad * 2) / bw, 600);
      H = Math.max(400, Math.min(2400, Math.round(bh * scale + pad * 2)));
      cx = (b.minX + b.maxX) / 2;
      cy = (b.minY + b.maxY) / 2;
    }
    out.width = W;
    out.height = H;
    const ctx = out.getContext("2d")!;
    this.draw(ctx, W, H, cx, cy, scale, false);
    return new Promise((res) => out.toBlob(res, "image/png"));
  }
}

function fmt(n: number): string {
  const r = Math.round(n * 1000) / 1000;
  return String(r);
}
