import type { Segment } from "../lang";
import { h } from "./dom";
import { bounds, niceStep, readPalette, type DrawingView, type Palette, type Scene } from "./views";

type V3 = [number, number, number];
const FOV = (45 * Math.PI) / 180;
const FLOATS = 13; // aA(3) aB(3) aC(2) aCol(4) aW(1)

const VERT = `
attribute vec3 aA; attribute vec3 aB; attribute vec2 aC; attribute vec4 aCol; attribute float aW;
uniform mat4 uVP; uniform vec2 uRes;
varying vec4 vCol;
void main() {
  vec4 pa = uVP * vec4(aA, 1.0);
  vec4 pb = uVP * vec4(aB, 1.0);
  vec2 sa = pa.xy / pa.w * uRes * 0.5;
  vec2 sb = pb.xy / pb.w * uRes * 0.5;
  vec2 d = sb - sa;
  float l = length(d);
  d = l > 0.0001 ? d / l : vec2(1.0, 0.0);
  vec2 n = vec2(-d.y, d.x);
  vec4 p = mix(pa, pb, aC.x);
  vec2 off = n * aC.y * aW * 0.5 + d * (aC.x * 2.0 - 1.0) * aW * 0.5;
  gl_Position = p;
  gl_Position.xy += off / (uRes * 0.5) * p.w;
  vCol = aCol;
