  private upload(buf: WebGLBuffer, L: Lines) {
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(L.data), gl.DYNAMIC_DRAW);
