    const stride = FLOATS * 4;
    const attr = (name: string, size: number, offset: number) => {
      const loc = gl.getAttribLocation(this.prog, name);
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc, size, gl.FLOAT, false, stride, offset * 4);
    };
    attr("aA", 3, 0);
    attr("aB", 3, 3);
    attr("aC", 2, 6);
    attr("aCol", 4, 8);
    attr("aW", 1, 12);
    gl.drawArrays(gl.TRIANGLES, 0, count);
  }

  private paint() {
    this.dirty = false;
    if (this.lost) return;
    const gl = this.gl;
    const W = this.canvas.width, H = this.canvas.height;
    if (!W || !H) return;
    const dpr = W / (this.canvas.clientWidth || W);
    if (this.staticDirty) {
      this.nStatic = this.upload(this.bufStatic, this.buildStatic());
      this.staticDirty = false;
    }
    const marker = this.buildMarker();
    const nMarker = this.upload(this.bufMarker, marker);
    const bg = parseColor(this.pal.paper);
    gl.viewport(0, 0, W, H);
    gl.clearColor(bg[0], bg[1], bg[2], 1);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.useProgram(this.prog);
    const vp = this.viewProj();
    gl.uniformMatrix4fv(this.uVP, false, vp);
    gl.uniform2f(this.uRes, W, H);
    // widths are CSS pixels; scale to device pixels inside the buffers via a uniform-free trick: re-upload is avoided by scaling here
    this.widthScale(dpr);
    this.drawBuffer(this.bufStatic, this.nStatic);
    this.drawBuffer(this.bufMarker, nMarker);
    this.placeLabels(vp);
  }

  private lastDpr = 1;
  private widthScale(dpr: number) {
    if (dpr !== this.lastDpr) {
      this.lastDpr = dpr;
      this.staticDirty = true;
    }
  }

  private placeLabels(vp: Float32Array) {
    const w = this.canvas.clientWidth, hgt = this.canvas.clientHeight;
    for (const k of ["X", "Y", "Z"] as const) {
      const p = this.axisEnds[k];
      const x = vp[0] * p[0] + vp[4] * p[1] + vp[8] * p[2] + vp[12];
      const y = vp[1] * p[0] + vp[5] * p[1] + vp[9] * p[2] + vp[13];
      const wv = vp[3] * p[0] + vp[7] * p[1] + vp[11] * p[2] + vp[15];
      const el = this.labels[k];
      if (wv <= 0) {
        el.style.visibility = "hidden";
        continue;
      }
      const sx = (x / wv * 0.5 + 0.5) * w;
      const sy = (1 - (y / wv * 0.5 + 0.5)) * hgt;
      el.style.visibility = sx < 0 || sy < 0 || sx > w || sy > hgt ? "hidden" : "visible";
      el.style.transform = `translate(${sx + 6}px, ${sy - 8}px)`;
    }
  }

  toPng(): Promise<Blob | null> {
    this.paint();
    return new Promise((res) => this.canvas.toBlob(res, "image/png"));
  }
}

function withAlpha(c: [number, number, number, number], a: number): [number, number, number, number] {
  return [c[0], c[1], c[2], c[3] * a];
}

export type { Segment };
