/** Statements per second for the speed slider; the last step runs at once. */
const SPEEDS = [2, 5, 10, 20, 40, 80, 150, 300, 600, 1500, Infinity];
const speedText = (lvl: number) => (SPEEDS[lvl] === Infinity ? "natychmiast" : `${SPEEDS[lvl]} poleceń/s`);

const isMac = /Mac|iPhone|iPad/.test(navigator.platform);
const MOD = isMac ? "⌘" : "Ctrl";
export const SHORTCUTS: { keys: string; action: string }[] = [
  { keys: `${MOD}+Enter`, action: "Uruchom program (lub kontynuuj po wstrzymaniu)" },
  { keys: `${MOD}+.`, action: "Wykonaj jeden krok" },
  { keys: "Esc", action: "Wstrzymaj lub wznów działający program" },
  { keys: `${MOD}+Shift+.`, action: "Resetuj rysunek" },
  { keys: "Strzałki, + , − , 0", action: "W widoku rysunku: przesuwanie lub obracanie, powiększenie, dopasowanie" },
];

const THEME_LABEL: Record<Theme, string> = { auto: "automatyczny", light: "jasny", dark: "ciemny" };
const THEME_ICON: Record<Theme, string> = { auto: "auto", light: "sun", dark: "moon" };

function inline(text: string): DocumentFragment {
  const f = document.createDocumentFragment();
  text.split("`").forEach((part, i) => f.append(i % 2 ? h("code", {}, part) : part));
  return f;
}

function codeBlock(source: string): HTMLElement {
  const pre = h("pre", { class: "sample" });
