    d.innerHTML = html;
    code.append(d);
  });
  pre.append(code);
  return pre;
}

export class App {
  private studio: Studio;
  private gl3d: boolean;
  private root: HTMLElement;
  private editor = new Editor();
  private view2d = new View2D();
  private view3d: View3D | null = null;
  private notice3d!: HTMLElement;
  private stage!: HTMLElement;
  private workspaceEl!: HTMLElement;
  private docsEl: HTMLElement | null = null;

  private runBtn!: HTMLButtonElement;
  private stepBtn!: HTMLButtonElement;
  private pauseBtn!: HTMLButtonElement;
  private resetBtn!: HTMLButtonElement;
  private speed!: HTMLInputElement;
  private speedOut!: HTMLElement;
  private status!: HTMLElement;
  private statusText!: HTMLElement;
  private jumpBtn!: HTMLButtonElement;
  private confirmBar!: HTMLElement;
  private confirmText!: HTMLElement;
  private restoreBar!: HTMLElement;
  private challengeBar!: HTMLElement;
  private verdictEl!: HTMLElement;
  private shareBox!: HTMLElement;
  private shareInput!: HTMLInputElement;
  private shareNote!: HTMLElement;
  private caption!: HTMLElement;
  private themeBtn!: HTMLButtonElement;
  private modeInputs: Record<Mode, HTMLInputElement> = {} as never;
  private tabs: Record<string, { tab: HTMLElement; panel: HTMLElement }> = {};
  private challengeList!: HTMLElement;
  private resetViewBtn!: HTMLButtonElement;

  private showGhost = true;
  private showRestore = false;
  private liveVisible = false;
  private liveTimer = 0;
  private lastFit = -1;
  private flashTimer = 0;
  private activeView: DrawingView = this.view2d;

  constructor(root: HTMLElement, studio: Studio, caps: { gl3d: boolean }) {
    this.root = root;
    this.studio = studio;
    this.gl3d = caps.gl3d;
    if (caps.gl3d) {
      try {
        this.view3d = new View3D();
      } catch {
        this.gl3d = false;
      }
    }
    this.build();
    this.applyTheme();
    studio.subscribe(() => this.sync());
    window.addEventListener("hashchange", () => this.route());
    window.addEventListener("keydown", (e) => this.onKey(e));
    matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => this.themeChanged());
    this.editor.setValue(studio.workspace.source);
    this.route();
    this.sync();
  }

  // ---------- construction ----------
  private build() {
    const header = h(
      "header",
      { class: "top" },
      h("a", { class: "brand", href: "#/", "aria-label": "Logomocja: pracownia" }, this.logo(), h("span", { class: "wordmark" }, "Logomocja")),
      h(
        "nav",
        { class: "nav", "aria-label": "Główna nawigacja" },
        h("a", { href: "#/", "data-route": "work" }, "Pracownia"),
        h("a", { href: "#/dokumentacja", "data-route": "docs" }, "Dokumentacja"),
      ),
      h("span", { class: "spacer" }),
      this.buildShortcuts(),
      (this.themeBtn = h("button", { class: "btn icon-btn", type: "button", onclick: () => this.cycleTheme() })),
    );
    this.workspaceEl = this.buildWorkspace();
    this.root.replaceChildren(
      h("a", { class: "skip", href: "#/" , onclick: (e: Event) => { e.preventDefault(); (document.querySelector("main") as HTMLElement | null)?.focus(); } }, "Przejdź do treści"),
      header,
      this.workspaceEl,
    );
  }

  private logo(): SVGSVGElement {
    const ns = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(ns, "svg");
    svg.setAttribute("viewBox", "0 0 32 32");
    svg.setAttribute("width", "28");
    svg.setAttribute("height", "28");
    svg.setAttribute("aria-hidden", "true");
    svg.innerHTML = `<rect width="32" height="32" rx="7" fill="var(--accent)"/><path d="M9 23V9h14v10H13v-6h6" fill="none" stroke="var(--accent-ink)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="9" cy="23" r="2.2" fill="#e7a664"/>`;
    return svg;
  }

  private buildShortcuts(): HTMLElement {
    const pop = h(
      "div",
      { id: "shortcuts", popover: "auto", class: "popover", role: "dialog", "aria-label": "Skróty klawiszowe" },
      h("h2", {}, "Skróty klawiszowe"),
      h("dl", {}, ...SHORTCUTS.flatMap((s) => [h("dt", {}, h("kbd", {}, s.keys)), h("dd", {}, s.action)])),
    );
    const btn = h("button", { class: "btn icon-btn", type: "button", popovertarget: "shortcuts", "aria-label": "Skróty klawiszowe", title: "Skróty klawiszowe" }, icon("keys"));
    return h("div", { class: "shortcuts-wrap" }, btn, pop);
  }

  private tabButton(id: string, label: string): HTMLElement {
    return h("button", { class: "tab", type: "button", role: "tab", id: `tab-${id}`, "aria-controls": `panel-${id}`, onclick: () => this.selectTab(id), onkeydown: (e: KeyboardEvent) => this.tabKeys(e) }, label);
  }

  private buildWorkspace(): HTMLElement {
    const ed = this.editor;
    ed.onInput = (text) => this.onEdit(text);

    const mkBtn = (label: string, ic: string, onclick: () => void, extra: Record<string, string> = {}) =>
      h("button", { class: "btn", type: "button", onclick, ...extra }, icon(ic), h("span", {}, label));

    this.runBtn = mkBtn("Uruchom", "play", () => this.studio.run(), { class: "btn primary", "aria-keyshortcuts": "Control+Enter", title: `Uruchom (${MOD}+Enter)` }) as HTMLButtonElement;
    this.stepBtn = mkBtn("Krok", "step", () => this.studio.step(), { "aria-keyshortcuts": "Control+.", title: `Jeden krok (${MOD}+.)` }) as HTMLButtonElement;
    this.pauseBtn = mkBtn("Wstrzymaj", "pause", () => this.studio.togglePause(), { "aria-keyshortcuts": "Escape", title: "Wstrzymaj lub wznów (Esc)" }) as HTMLButtonElement;
    this.resetBtn = mkBtn("Reset", "reset", () => this.studio.reset(), { "aria-keyshortcuts": "Control+Shift+.", title: `Resetuj rysunek (${MOD}+Shift+.)` }) as HTMLButtonElement;

    this.speed = h("input", { type: "range", min: 0, max: SPEEDS.length - 1, step: 1, id: "speed", value: this.studio.workspace.speedLevel, "aria-describedby": "speed-out" });
    this.speedOut = h("output", { id: "speed-out", for: "speed" });
    this.speed.addEventListener("input", () => {
      const lvl = Number(this.speed.value);
      this.studio.workspace.setSpeedLevel(lvl);
      this.studio.session.setSpeed(SPEEDS[lvl]);
      this.speedOut.textContent = speedText(lvl);
    });
    this.studio.session.setSpeed(SPEEDS[this.studio.workspace.speedLevel]);
    this.speedOut.textContent = speedText(this.studio.workspace.speedLevel);

    const toolbar = h(
      "div",
      { class: "toolbar", role: "toolbar", "aria-label": "Sterowanie programem" },
      h("div", { class: "btn-row" }, this.runBtn, this.stepBtn, this.pauseBtn, this.resetBtn),
      h("label", { class: "speed", for: "speed" }, h("span", { class: "speed-label" }, "Szybkość"), this.speed, this.speedOut),
    );

    this.confirmText = h("span", {});
    this.confirmBar = h(
      "div",
      { class: "bar warn", role: "group", "aria-label": "Potwierdzenie wczytania", hidden: true },
      this.confirmText,
      h("span", { class: "bar-actions" },
        h("button", { class: "btn small primary", type: "button", onclick: () => { this.studio.confirmLoad(); this.afterReplace(); } }, "Wczytaj i zastąp"),
        h("button", { class: "btn small", type: "button", onclick: () => this.studio.cancelLoad() }, "Anuluj")),
    );
    this.restoreBar = h(
      "div",
      { class: "bar info", role: "group", "aria-label": "Przywracanie szkicu", hidden: true },
      h("span", {}, "Poprzedni szkic został zachowany."),
      h("button", { class: "btn small", type: "button", onclick: () => { this.showRestore = false; this.studio.restore(); } }, "Przywróć poprzedni szkic"),
    );

    this.challengeBar = this.buildChallengeBar();

    this.statusText = h("span", { class: "status-text" });
    this.jumpBtn = h("button", { class: "btn small", type: "button", onclick: () => this.jumpToError() }, "Pokaż w kodzie") as HTMLButtonElement;
    this.status = h("div", { class: "status", id: "status", role: "status", "aria-live": "polite" }, this.statusText, this.jumpBtn);

    const fileInput = h("input", { type: "file", accept: ".logo,.txt,text/plain", class: "visually-hidden", tabindex: -1, "aria-hidden": "true", onchange: (e: Event) => this.openFile(e.target as HTMLInputElement) });
    const fileRow = h(
      "div",
      { class: "file-row" },
      mkBtn("Otwórz plik", "open", () => fileInput.click(), { title: "Otwórz plik .logo" }),
      mkBtn("Pobierz .logo", "download", () => this.download(), { title: "Pobierz program jako plik .logo" }),
      mkBtn("Udostępnij", "share", () => this.toggleShare(), { "aria-expanded": "false", "aria-controls": "share-box", id: "share-btn" }),
      fileInput,
    );
    this.shareInput = h("input", { type: "text", readonly: true, id: "share-url", class: "share-url", "aria-label": "Adres do udostępnienia" });
    this.shareNote = h("span", { class: "share-note", role: "status" });
    this.shareBox = h(
      "div",
      { class: "bar info share-box", id: "share-box", hidden: true },
      h("label", { for: "share-url" }, "Link do programu"),
      this.shareInput,
      h("button", { class: "btn small primary", type: "button", onclick: () => this.copyShare() }, "Kopiuj link"),
      this.shareNote,
    );

    const panelCode = h("div", { class: "panel panel-code", role: "tabpanel", id: "panel-code", "aria-labelledby": "tab-code" }, this.challengeBar, toolbar, this.confirmBar, this.restoreBar, ed.el, this.status, fileRow, this.shareBox);
    const panelEx = h("div", { class: "panel", role: "tabpanel", id: "panel-examples", "aria-labelledby": "tab-examples", hidden: true }, this.buildExamples());
    const panelCh = h("div", { class: "panel", role: "tabpanel", id: "panel-challenges", "aria-labelledby": "tab-challenges", hidden: true }, (this.challengeList = h("div", {})));
    const tabs = [
      ["code", "Kod", panelCode],
      ["examples", "Przykłady", panelEx],
      ["challenges", "Wyzwania", panelCh],
    ] as const;
    const tablist = h("div", { class: "tabs", role: "tablist", "aria-label": "Panel kodu" });
    for (const [id, label, panel] of tabs) {
      const tab = this.tabButton(id, label);
      tablist.append(tab);
      this.tabs[id] = { tab, panel };
    }
    this.selectTab("code");

    // ----- drawing pane -----
    const mode = (m: Mode, label: string) => {
      const input = h("input", { type: "radio", name: "mode", value: m, id: `mode-${m}`, onchange: () => this.studio.setMode(m) });
      this.modeInputs[m] = input;
      return h("span", { class: "seg" }, input, h("label", { for: `mode-${m}` }, label));
    };
    const vbtn = (label: string, ic: string, onclick: () => void) => h("button", { class: "btn icon-btn", type: "button", "aria-label": label, title: label, onclick }, icon(ic));
    this.resetViewBtn = vbtn("Domyślny widok kamery", "box", () => this.activeView.resetView()) as HTMLButtonElement;
    const viewbar = h(
      "div",
      { class: "viewbar", role: "toolbar", "aria-label": "Widok rysunku" },
      h("div", { class: "segmented", role: "radiogroup", "aria-label": "Tryb rysowania" }, mode("2d", "2D"), mode("3d", "3D")),
      h("span", { class: "spacer" }),
      vbtn("Pomniejsz", "zoomOut", () => this.activeView.zoomBy(0.8)),
      vbtn("Powiększ", "zoomIn", () => this.activeView.zoomBy(1.25)),
      vbtn("Dopasuj rysunek do okna", "fit", () => this.activeView.fit()),
      this.resetViewBtn,
      vbtn("Zapisz rysunek jako PNG", "png", () => this.exportPng()),
    );
    this.notice3d = h(
      "div",
      { class: "notice3d", role: "status", hidden: true },
      h("h2", {}, "Widok 3D jest wyłączony"),
      h("p", {}, "Ta przeglądarka lub urządzenie nie udostępnia WebGL, a bez niego nie da się narysować przestrzeni. Tryb 2D działa normalnie."),
      h("p", { class: "notice-count" }),
    );
    this.stage = h("div", { class: "stage-wrap" }, this.view2d.el, this.view3d?.el ?? null, this.notice3d);
    this.caption = h("div", { class: "caption", "aria-live": "off" });
    const paneView = h("section", { class: "pane pane-view", "aria-label": "Rysunek" }, viewbar, this.stage, this.caption);
    const paneCode = h("section", { class: "pane pane-code", "aria-label": "Program" }, tablist, panelCode, panelEx, panelCh);
    return h("main", { class: "work", id: "main", tabindex: -1 }, paneCode, paneView);
  }

  private buildExamples(): HTMLElement {
    return h(
      "div",
      { class: "list-wrap" },
      h("h2", { class: "panel-title" }, "Przykładowe programy"),
      h("p", { class: "muted" }, "Wczytanie przykładu przełącza tryb. Jeśli masz niezapisane zmiany, najpierw zapytamy o zgodę."),
      h(
        "ul",
        { class: "rows" },
        ...EXAMPLES.map((e) =>
          h(
            "li",
            { class: "row" },
            h("div", { class: "row-main" }, h("strong", {}, e.name), h("span", { class: "badge" }, e.mode.toUpperCase()), h("p", { class: "muted" }, e.blurb)),
            h("button", { class: "btn small", type: "button", "aria-label": `Wczytaj przykład ${e.name} (${e.mode.toUpperCase()})`, onclick: () => this.loadExample(e.id) }, "Wczytaj"),
          ),
        ),
      ),
    );
  }

  private buildChallengeBar(): HTMLElement {
    this.verdictEl = h("div", { class: "verdict", role: "status", "aria-live": "polite" });
    return h("div", { class: "challenge-bar", hidden: true });
  }

  // ---------- behaviour ----------
  private selectTab(id: string) {
    for (const [k, t] of Object.entries(this.tabs)) {
      const on = k === id;
      t.tab.setAttribute("aria-selected", String(on));
      t.tab.tabIndex = on ? 0 : -1;
      t.panel.hidden = !on;
    }
    if (id === "challenges") this.renderChallengeList();
  }

  private tabKeys(e: KeyboardEvent) {
    const ids = Object.keys(this.tabs);
    const cur = ids.findIndex((k) => this.tabs[k].tab === e.currentTarget);
    let next = -1;
    if (e.key === "ArrowRight") next = (cur + 1) % ids.length;
    else if (e.key === "ArrowLeft") next = (cur - 1 + ids.length) % ids.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = ids.length - 1;
    if (next < 0) return;
    e.preventDefault();
    this.selectTab(ids[next]);
    this.tabs[ids[next]].tab.focus();
  }

  private onEdit(text: string) {
    this.showRestore = false;
    if (!this.studio.edit(text)) this.editor.setValue(this.studio.workspace.source);
    this.liveVisible = false;
    clearTimeout(this.liveTimer);
    this.liveTimer = window.setTimeout(() => {
      this.liveVisible = true;
      this.sync();
    }, 700);
  }

  private loadExample(id: string) {
    const before = this.studio.workspace.restorable();
    const r = this.studio.loadExample(id);
    this.selectTab("code");
    if (r === "loaded") this.noteReplaced(before);
    else this.editor.focus();
  }

  private noteReplaced(before: string | null) {
    const after = this.studio.workspace.restorable();
    if (after !== null && after !== before) this.showRestore = true;
    this.sync();
  }

  private afterReplace() {
    if (this.studio.workspace.restorable() !== null) this.showRestore = true;
    this.sync();
  }

  /** Called by the documentation page. */
  tryExample(source: string, mode: Mode, label: string) {
    const before = this.studio.workspace.restorable();
    const r = this.studio.requestLoad({ source, mode, label });
    location.hash = "#/";
    this.selectTab("code");
    if (r === "loaded") this.noteReplaced(before);
  }

  private openFile(input: HTMLInputElement) {
    const file = input.files?.[0];
    input.value = "";
    if (!file) return;
    file.text().then((text) => {
      const before = this.studio.workspace.restorable();
      const r = this.studio.requestLoad({ source: parseLogoFile(text), mode: this.studio.workspace.mode, label: file.name });
      if (r === "loaded") this.noteReplaced(before);
      else this.sync();
    });
  }

  private download() {
    const blob = new Blob([this.studio.workspace.source], { type: "text/plain;charset=utf-8" });
    this.saveBlob(blob, logoFileName(this.studio.workspace.mode));
  }

  private saveBlob(blob: Blob, name: string) {
    const url = URL.createObjectURL(blob);
    const a = h("a", { href: url, download: name });
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }

  private async exportPng() {
    if (this.studio.workspace.mode === "3d" && !this.view3d) return this.flash("PNG z widoku 3D jest niedostępny bez WebGL.");
    const blob = await this.activeView.toPng();
    if (!blob) return this.flash("Nie udało się zapisać obrazu.");
    this.saveBlob(blob, `logomocja-${this.studio.workspace.mode}.png`);
    this.flash("Zapisano rysunek jako PNG.");
  }

  private toggleShare() {
    const open = this.shareBox.hidden;
    this.shareBox.hidden = !open;
    document.getElementById("share-btn")?.setAttribute("aria-expanded", String(open));
    if (open) {
      const w = this.studio.workspace;
      this.shareInput.value = encodePermalink(location.href, w.source, w.mode);
      this.shareNote.textContent = "";
      this.shareInput.focus();
      this.shareInput.select();
    }
  }

  private async copyShare() {
    this.shareInput.select();
    try {
      await navigator.clipboard.writeText(this.shareInput.value);
      this.shareNote.textContent = "Skopiowano do schowka.";
    } catch {
      this.shareNote.textContent = "Nie można skopiować automatycznie: zaznaczony link skopiuj ręcznie.";
    }
  }

  private flash(msg: string) {
    this.statusText.textContent = msg;
    clearTimeout(this.flashTimer);
    this.flashTimer = window.setTimeout(() => this.sync(), 5000);
    this.flashing = true;
  }
  private flashing = false;

  private jumpToError() {
    const e = this.studio.session.error ?? this.studio.liveError;
    if (e) this.editor.focus({ line: e.line, column: e.column });
  }

  private cycleTheme() {
    const order: Theme[] = ["auto", "light", "dark"];
    const w = this.studio.workspace;
    w.setTheme(order[(order.indexOf(w.theme) + 1) % 3]);
    this.applyTheme();
  }

  private applyTheme() {
    const t = this.studio.workspace.theme;
    if (t === "auto") document.documentElement.removeAttribute("data-theme");
    else document.documentElement.setAttribute("data-theme", t);
    this.themeBtn.replaceChildren(icon(THEME_ICON[t]));
    const label = `Motyw: ${THEME_LABEL[t]}. Zmień motyw`;
    this.themeBtn.setAttribute("aria-label", label);
    this.themeBtn.title = label;
    this.themeChanged();
  }

  private themeChanged() {
    this.view2d.themeChanged();
    this.view3d?.themeChanged();
  }

  private onKey(e: KeyboardEvent) {
    if (this.docsEl && !this.docsEl.hidden) return;
    const mod = e.ctrlKey || e.metaKey;
    if (mod && e.key === "Enter") {
      e.preventDefault();
      this.studio.run();
    } else if (mod && e.code === "Period" && !e.shiftKey) {
      e.preventDefault();
      this.studio.step();
    } else if (mod && e.code === "Period" && e.shiftKey) {
      e.preventDefault();
      this.studio.reset();
    } else if (e.key === "Escape" && !document.querySelector(":popover-open")) {
      const s = this.studio.session.state;
      if (s === "running" || s === "paused") {
        e.preventDefault();
        this.studio.togglePause();
      }
    }
  }

  // ---------- rendering the state ----------
  sync() {
    const st = this.studio;
    const ses = st.session;
    const ws = st.workspace;
    // editor
    if (this.editor.value !== ws.source) this.editor.setValue(ws.source);
    this.editor.setReadonly(ses.state === "running");
    const liveErr = this.liveVisible ? st.liveError : null;
    const err = ses.error ?? liveErr;
    this.editor.setError(err ? { line: err.line, column: err.column } : null);
    this.editor.setExecLine(ses.state === "running" || ses.state === "paused" ? ses.line : null);

    // buttons
    const live = ses.state === "running" || ses.state === "paused";
    this.pauseBtn.disabled = !live;
    this.pauseBtn.replaceChildren(icon(ses.state === "paused" ? "play" : "pause"), h("span", {}, ses.state === "paused" ? "Wznów" : "Wstrzymaj"));
    this.runBtn.disabled = ses.state === "running";
    this.stepBtn.disabled = ses.state === "running";
    this.resetBtn.disabled = ses.state === "idle" && !ses.segments.length;

    // mode
    this.modeInputs[ws.mode].checked = true;
    this.modeInputs["3d"].toggleAttribute("data-off", !this.gl3d);
    this.resetViewBtn.hidden = ws.mode !== "3d";

    // confirmation / restore / challenge
    this.confirmBar.hidden = !ws.pending;
    if (ws.pending) this.confirmText.textContent = `Masz niezapisane zmiany w szkicu ${ws.pending.mode.toUpperCase()}. Wczytanie „${ws.pending.label}” zastąpi go.`;
    this.restoreBar.hidden = !(this.showRestore && ws.restorable() !== null);
    this.syncChallengeBar();

    // status line
    if (!this.flashing || true) this.syncStatus(err, liveErr);

    // views
    this.syncViews();
  }

  private syncStatus(err: { line: number; column: number; message: string } | null, liveErr: unknown) {
    if (this.flashing) {
      this.flashing = false;
      // a flash keeps its message until the timer fires; do not overwrite on unrelated updates
      if (this.statusText.dataset.flash === "1") return;
    }
    const ses = this.studio.session;
    this.status.classList.toggle("is-error", !!err);
    this.status.setAttribute("role", ses.error ? "alert" : "status");
    this.jumpBtn.hidden = !err;
    if (err) {
      const kind = ses.error ? "Błąd" : "Składnia";
      this.statusText.textContent = `${kind} w wierszu ${err.line}, kolumnie ${err.column}: ${err.message}`;
      return;
    }
    const n = ses.segments.length;
    const stale = this.studio.stale ? " Kod zmieniono po uruchomieniu, więc rysunek jest nieaktualny." : "";
    const text: Record<string, string> = {
      idle: n ? "Gotowe." : "Gotowe. Uruchom program albo wykonuj go krok po kroku.",
      running: `Działa${ses.line ? `, wiersz ${ses.line}` : ""}. Odcinków: ${n}.`,
      paused: ses.line ? `Wstrzymano przed wierszem ${ses.line}. Odcinków: ${n}.` : `Wstrzymano. Odcinków: ${n}.`,
      finished: `Zakończono. Narysowano odcinków: ${n}.${stale}`,
    };
    this.statusText.textContent = text[ses.state] ?? "";
  }

  private syncChallengeBar() {
    const st = this.studio;
    const c = st.activeChallenge;
    this.challengeBar.hidden = !c;
    if (!c) return;
    // rebuild only when the challenge changes or the verdict changes
    const key = `${c.id}|${st.verdict?.passed}|${st.verdict?.reason}|${this.showGhost}|${st.progress.isSolved(c.id)}`;
    if (this.challengeBar.dataset.key === key) return;
    this.challengeBar.dataset.key = key;
    const v = st.verdict;
    this.verdictEl = h("div", { class: `verdict ${v ? (v.passed ? "pass" : "fail") : ""}`, role: "status", "aria-live": "polite" }, v ? h("strong", {}, v.passed ? "Zaliczone. " : "Jeszcze nie. ") : null, v ? v.reason : null);
    this.challengeBar.replaceChildren(
      h("div", { class: "challenge-head" },
        h("strong", {}, `Wyzwanie: ${c.title}`),
        st.progress.isSolved(c.id) ? h("span", { class: "badge ok" }, "rozwiązane") : null,
        h("button", { class: "btn icon-btn small", type: "button", "aria-label": "Zamknij wyzwanie", title: "Zamknij wyzwanie", onclick: () => st.closeChallenge() }, icon("close"))),
      h("p", {}, c.task),
      h("div", { class: "challenge-actions" },
        h("button", { class: "btn small primary", type: "button", onclick: () => st.checkChallenge() }, icon("check"), h("span", {}, "Sprawdź rozwiązanie")),
        h("label", { class: "check" }, h("input", { type: "checkbox", checked: this.showGhost, onchange: (e: Event) => { this.showGhost = (e.target as HTMLInputElement).checked; this.sync(); } }), "Pokaż wzór na rysunku")),
      h("details", {}, h("summary", {}, "Podpowiedź"), h("p", {}, c.hint)),
      this.verdictEl,
    );
  }

  private syncViews() {
    const st = this.studio;
    const mode = st.workspace.mode;
    const ses = st.session;
    const useGl = mode === "3d" && !!this.view3d;
    const view: DrawingView | null = mode === "2d" ? this.view2d : this.view3d;
    this.view2d.el.hidden = mode !== "2d";
    if (this.view3d) this.view3d.el.hidden = !useGl;
    this.notice3d.hidden = !(mode === "3d" && !this.view3d);
    if (!this.notice3d.hidden) {
      const n = this.notice3d.querySelector(".notice-count");
      if (n) n.textContent = `Program jest jednak wykonywany: narysowano odcinków: ${ses.segments.length}.`;
    }
    if (view) {
      const changed = this.activeView !== view;
      this.activeView = view;
      if (changed) view.resize();
      view.setScene({ segments: ses.segments, turtle: ses.turtle, ghost: this.showGhost ? st.ghost : [] });
      if (this.lastFit !== st.fitRequests || changed) {
        this.lastFit = st.fitRequests;
        view.fit();
      }
    }
    const t = ses.turtle;
    const r = (n: number) => Math.round(n * 100) / 100;
    this.caption.textContent = `Odcinków: ${ses.segments.length} · żółw: (${r(t.pos[0])}, ${r(t.pos[1])}${mode === "3d" ? `, ${r(t.pos[2])}` : ""}) · pióro ${t.pen ? "opuszczone" : "podniesione"}`;
  }

  /** Resolves when the current drawing has been painted (two animation frames). */
  async painted(): Promise<void> {
    this.sync();
    (this.activeView as unknown as { paintNow?: () => void }).paintNow?.();
    await new Promise<void>((r) => requestAnimationFrame(() => requestAnimationFrame(() => r())));
  }

  // ---------- challenges list ----------
  private renderChallengeList() {
    const st = this.studio;
    this.challengeList.replaceChildren(
      h("div", { class: "list-wrap" },
        h("h2", { class: "panel-title" }, "Wyzwania"),
        h("p", { class: "muted" }, `Rozwiązane: ${st.progress.solvedCount()} z ${CHALLENGES.length}. Postęp zapisuje się w tej przeglądarce.`),
        h("ul", { class: "rows" },
          ...CHALLENGES.map((c) => {
            const done = st.progress.isSolved(c.id);
            return h("li", { class: "row" },
              h("div", { class: "row-main" },
                h("strong", {}, c.title),
                h("span", { class: "badge" }, c.mode.toUpperCase()),
                done ? h("span", { class: "badge ok" }, icon("check"), "rozwiązane") : null,
                h("p", { class: "muted" }, c.task)),
              h("button", { class: "btn small", type: "button", "aria-label": `${done ? "Wróć do" : "Rozpocznij"} wyzwanie ${c.title}`, onclick: () => { st.startChallenge(c.id); this.selectTab("code"); this.editor.focus(); } }, done ? "Wróć" : "Rozpocznij"));
          }))),
    );
  }

  // ---------- routing ----------
  private route() {
    const hash = location.hash;
    if (hash.startsWith("#/u/")) {
      const before = this.studio.workspace.restorable();
      const r = this.studio.openHash(hash);
      history.replaceState(null, "", location.pathname + location.search + "#/");
      this.showWorkspace();
      if (r === "opened") {
        this.noteReplaced(before);
        this.flashMsg("Wczytano program z linku i uruchomiono go.");
      } else this.flashMsg("Ten link jest uszkodzony, więc go pominięto.");
      return;
    }
    if (hash.startsWith("#/dokumentacja")) {
      this.showDocs(hash.slice("#/dokumentacja".length).replace(/^\//, ""));
      return;
    }
    this.showWorkspace();
  }

  private flashMsg(msg: string) {
    this.statusText.textContent = msg;
    this.statusText.dataset.flash = "1";
    clearTimeout(this.flashTimer);
    this.flashTimer = window.setTimeout(() => {
      delete this.statusText.dataset.flash;
      this.sync();
    }, 6000);
  }

  private setNavCurrent(which: "work" | "docs") {
    document.querySelectorAll<HTMLElement>(".nav a").forEach((a) => {
      if (a.dataset.route === which) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    });
  }

  private showWorkspace() {
    this.workspaceEl.hidden = false;
    if (this.docsEl) this.docsEl.hidden = true;
    this.setNavCurrent("work");
    document.title = "Logomocja: pracownia żółwia";
    requestAnimationFrame(() => {
      this.view2d.resize();
      this.view3d?.resize();
    });
  }

  private showDocs(anchor: string) {
    if (!this.docsEl) {
      this.docsEl = this.buildDocs();
      this.root.append(this.docsEl);
    }
    this.workspaceEl.hidden = true;
    this.docsEl.hidden = false;
    this.setNavCurrent("docs");
    document.title = "Dokumentacja języka: Logomocja";
    const target = anchor ? this.docsEl.querySelector<HTMLElement>(`[id="${CSS.escape(anchor)}"]`) : null;
    if (target) target.scrollIntoView();
    else this.docsEl.scrollTop = 0;
  }

  private buildDocs(): HTMLElement {
    const tocItems: [string, string][] = [["start", "Pierwszy program"], ["polecenia", "Polecenia"]];
    const secs = DOC_SECTIONS;
    const sectionEl = (s: (typeof secs)[number]) =>
      h("section", { class: "doc-section", id: s.id }, h("h2", {}, s.title), ...s.text.map((t) => h("p", {}, inline(t))),
        ...s.examples.map((e) => this.docExample(e.source, e.mode, e.caption)));
    const start = sectionEl(secs[0]);
    const rest = secs.slice(1);
    for (const s of rest) tocItems.push([s.id, s.title]);
    tocItems.push(["skroty", "Skróty klawiszowe"]);

    const table = h("table", { class: "cmd-table" },
      h("caption", {}, "Wszystkie polecenia. Każdy angielski odpowiednik działa tak samo."),
      h("thead", {}, h("tr", {}, h("th", { scope: "col" }, "Polecenie"), h("th", { scope: "col" }, "Angielski"), h("th", { scope: "col" }, "Zapis"))),
      h("tbody", {}, ...COMMAND_DOCS.map((c) => h("tr", {},
        h("td", {}, h("a", { href: `#/dokumentacja/cmd-${c.names[0]}` }, h("code", {}, c.names.join(", ")))),
        h("td", {}, c.english.length ? h("code", {}, c.english.join(", ")) : "—"),
        h("td", {}, h("code", {}, c.syntax))))));

    const cmds = COMMAND_DOCS.map((c) =>
      h("section", { class: "cmd", id: `cmd-${c.names[0]}` },
        h("h3", {}, h("code", {}, c.names.join(", ")), c.english.length ? h("span", { class: "alt" }, ` · ${c.english.join(", ")}`) : null, c.only3d ? h("span", { class: "badge" }, "tylko 3D") : null),
        h("p", {}, h("code", { class: "syntax" }, c.syntax)),
        h("p", {}, inline(c.summary)),
        this.docExample(c.example.source, c.example.mode, "Przykład")));

    const shortcuts = h("section", { class: "doc-section", id: "skroty" }, h("h2", {}, "Skróty klawiszowe"),
      h("dl", { class: "kbd-list" }, ...SHORTCUTS.flatMap((s) => [h("dt", {}, h("kbd", {}, s.keys)), h("dd", {}, s.action)])));

    const toc = h("nav", { class: "toc", "aria-label": "Spis treści" }, h("h2", {}, "Spis treści"),
      h("ul", {}, ...tocItems.map(([id, label]) => h("li", {}, h("a", { href: `#/dokumentacja/${id}` }, label)))));
    const article = h("article", { class: "doc" },
      h("h1", {}, "Dokumentacja języka"),
      h("p", { class: "lead" }, "Logomocja rozumie polskie i angielskie polecenia języka Logo. Przykłady możesz od razu wypróbować w pracowni."),
      start,
      h("section", { class: "doc-section", id: "polecenia" }, h("h2", {}, "Polecenia"), table, ...cmds),
      ...rest.map(sectionEl),
      shortcuts);
    return h("main", { class: "docs", id: "docs", tabindex: -1 }, toc, article);
  }

  private docExample(source: string, mode: Mode, caption: string): HTMLElement {
    return h("figure", { class: "example" },
      h("figcaption", {}, caption, h("span", { class: "badge" }, mode.toUpperCase())),
      codeBlock(source),
      h("button", { class: "btn small", type: "button", "aria-label": `Wypróbuj w pracowni: ${caption}`, onclick: () => this.tryExample(source, mode, caption) }, icon("play"), h("span", {}, "Wypróbuj")));
  }
}
