import { Studio } from "./studio";
import { browserStorage } from "./storage";
import { App } from "./ui/app";
import { View3D } from "./ui/view3d";

const scheduler = {
  request: (cb: (now: number) => void) => requestAnimationFrame(cb),
  cancel: (id: number) => cancelAnimationFrame(id),
};

const studio = new Studio(browserStorage(), scheduler);
const app = new App(document.getElementById("app")!, studio, { gl3d: View3D.supported() });

const api = studio.api();
// Testing hook: `run` is pure; `open` loads into the editor, runs to the end and resolves once painted.
(window as unknown as { logomocja: unknown }).logomocja = {
  version: api.version,
  run: api.run,
  open: async (source: string, mode: "2d" | "3d") => {
    const result = await api.open(source, mode);
    await app.painted();
    return result;
  },
};
