.editor:focus-within { outline: 2px solid var(--focus); outline-offset: -2px; }
.editor.locked { background: color-mix(in srgb, var(--surface) 92%, var(--text)); }
.scroller { flex: 1; min-width: 0; overflow: auto; display: flex; align-items: flex-start; font: 14px/var(--lh) var(--mono); font-variant-ligatures: none; tab-size: 2; }
.gutter { position: sticky; left: 0; z-index: 2; flex: none; min-height: 100%; padding: 10px 0; background: var(--panel); border-right: 1px solid var(--line); color: var(--muted); text-align: right; user-select: none; }
.ln { height: var(--lh); padding: 0 0.6rem 0 0.8rem; font-size: 12.5px; min-width: 3.2ch; box-sizing: content-box; }
.ln.exec { color: var(--accent); font-weight: 700; background: var(--accent-soft); }
.ln.bad { color: var(--error); font-weight: 700; background: color-mix(in srgb, var(--error) 14%, transparent); }
.code { position: relative; flex: 1; min-width: 0; padding: 10px 0; }
.overlay { position: absolute; left: 0; right: 0; top: 10px; padding: 0 0.75rem; white-space: pre; pointer-events: none; min-width: 100%; }
.overlay .l { height: var(--lh); }
.l.exec { background: var(--accent-soft); box-shadow: -100vw 0 0 var(--accent-soft), 100vw 0 0 var(--accent-soft); }
.l.bad { background: color-mix(in srgb, var(--error) 9%, transparent); }
.input { display: block; position: relative; width: 100%; margin: 0; padding: 0 0.75rem; border: 0; outline: 0; background: transparent; color: transparent; -webkit-text-fill-color: transparent; caret-color: var(--text); font: inherit; line-height: var(--lh); white-space: pre; resize: none; overflow: hidden; tab-size: 2; border-radius: 0; }
.t-kw { color: var(--t-kw); font-weight: 600; }
.t-num { color: var(--t-num); }
.t-str { color: var(--t-str); }
.t-str::before { content: ""; display: inline-block; width: 0.7em; height: 0.7em; margin-right: 0.25em; border-radius: 2px; background: var(--sw, transparent); border: 1px solid var(--line); vertical-align: -0.05em; }
.t-com { color: var(--t-com); font-style: italic; }
.t-rep { color: var(--t-rep); font-weight: 600; }
.t-br { color: var(--t-br); font-weight: 600; }
.t-op { color: var(--t-op); }
.err { text-decoration: underline wavy var(--error); text-decoration-thickness: 1.5px; text-underline-offset: 3px; text-decoration-skip-ink: none; }

/* ---------- drawing pane ---------- */
.pane-view { background: var(--bg); }
.viewbar { display: flex; align-items: center; gap: 0.375rem; padding: 0.375rem 0.75rem; border-bottom: 1px solid var(--line); background: var(--panel); flex-wrap: wrap; }
.segmented { display: inline-flex; border: 1px solid var(--line); border-radius: var(--r); overflow: hidden; background: var(--surface); }
.seg { position: relative; display: inline-flex; }
.seg input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
.seg label { display: inline-flex; align-items: center; min-height: 36px; padding: 0 1rem; font-weight: 600; font-size: 0.9375rem; color: var(--muted); cursor: pointer; transition: background-color 150ms, color 150ms; }
.seg input:checked + label { background: var(--accent); color: var(--accent-ink); }
.seg input:not(:checked):hover + label { background: var(--accent-soft); color: var(--text); }
.seg input:focus-visible + label { outline: 2px solid var(--focus); outline-offset: -3px; }
.seg input[data-off] + label::after { content: " (wył.)"; font-weight: 400; margin-left: 0.25em; }
.stage-wrap { position: relative; flex: 1; min-height: 0; background: var(--paper); }
.view { position: absolute; inset: 0; }
canvas.stage { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: grab; outline-offset: -3px; }
canvas.stage.grabbing { cursor: grabbing; }
.axis-label { position: absolute; left: 0; top: 0; font: 700 13px var(--font); pointer-events: none; will-change: transform; }
.ax-x { color: var(--axis-x); } .ax-y { color: var(--axis-y); } .ax-z { color: var(--axis-z); }
.caption { padding: 0.375rem 0.75rem; border-top: 1px solid var(--line); background: var(--panel); font: 0.8125rem var(--mono); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.notice3d { position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; padding: 2rem; background: var(--paper); color: var(--paper-ink); }
.notice3d h2 { margin: 0 0 0.5rem; }
.notice3d p { max-width: 46ch; margin: 0.25rem 0; }

/* ---------- popover ---------- */
.popover { position: fixed; inset: auto; top: 56px; right: 12px; margin: 0; width: min(26rem, calc(100vw - 24px)); padding: 0.75rem 1rem 1rem; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); color: var(--text); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18); }
.popover h2 { font-size: 1.0625rem; margin: 0 0 0.5rem; }
dl { margin: 0; }
.popover dl, .kbd-list { display: grid; grid-template-columns: auto 1fr; gap: 0.5rem 1rem; align-items: baseline; }
dt { margin: 0; } dd { margin: 0; }
kbd { display: inline-block; padding: 0.1rem 0.4rem; border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 5px; background: var(--panel); font-size: 0.8125rem; white-space: nowrap; }

/* ---------- documentation ---------- */
.docs { flex: 1; min-height: 0; overflow: auto; display: grid; grid-template-columns: 16rem minmax(0, 1fr); gap: 2rem; padding: 1.5rem clamp(1rem, 4vw, 3rem) 4rem; outline: none; scroll-behavior: auto; }
.toc { position: sticky; top: 0; align-self: start; font-size: 0.9375rem; }
.toc h2 { font-size: 0.8125rem; text-transform: none; color: var(--muted); margin: 0 0 0.5rem; font-weight: 600; }
.toc ul { list-style: none; margin: 0; padding: 0; }
.toc a { display: block; padding: 0.3rem 0.5rem; border-radius: 6px; color: var(--text); text-decoration: none; }
.toc a:hover { background: var(--accent-soft); }
.doc { max-width: 78ch; min-width: 0; }
.doc h1 { font-size: 1.75rem; margin: 0 0 0.5rem; }
.doc h2 { font-size: 1.375rem; margin: 2.5rem 0 0.5rem; scroll-margin-top: 1rem; }
.doc h3 { font-size: 1.125rem; margin: 2rem 0 0.25rem; scroll-margin-top: 1rem; }
.doc h3 .alt { color: var(--muted); font-weight: 400; font-family: var(--mono); font-size: 0.875rem; }
.doc p { max-width: 70ch; }
.lead { font-size: 1.0625rem; color: var(--muted); }
.cmd { padding-bottom: 0.5rem; border-bottom: 1px solid var(--line); }
.syntax { display: inline-block; font-size: 0.9375rem; padding: 0.15rem 0.5rem; }
.cmd-table { width: 100%; border-collapse: collapse; margin: 1rem 0; font-size: 0.9375rem; display: block; overflow-x: auto; }
.cmd-table caption { text-align: left; color: var(--muted); padding: 0 0 0.5rem; }
.cmd-table th, .cmd-table td { text-align: left; padding: 0.4rem 0.75rem 0.4rem 0; border-bottom: 1px solid var(--line); vertical-align: top; }
.example { margin: 0.75rem 0 1rem; }
.example figcaption { font-size: 0.8125rem; color: var(--muted); margin-bottom: 0.25rem; }
.example figcaption .badge { margin-left: 0.5rem; }
pre.sample { margin: 0 0 0.5rem; padding: 0.75rem 1rem; background: var(--surface); border: 1px solid var(--line); border-radius: var(--r); overflow-x: auto; font-size: 0.875rem; line-height: 1.55; }
pre.sample code { background: none; padding: 0; font-size: inherit; display: block; }
pre.sample code div { white-space: pre; }

/* ---------- small screens: drawing on top, code below ---------- */
@media (max-width: 900px) {
  .work { grid-template-columns: 1fr; grid-template-rows: minmax(210px, 38dvh) minmax(0, 1fr); }
  .pane-view { order: -1; }
  .pane-code { border-right: 0; border-top: 1px solid var(--line); }
  .docs { grid-template-columns: 1fr; gap: 1rem; padding-top: 1rem; }
  .toc { position: static; }
  .toc ul { display: flex; flex-wrap: wrap; gap: 0.25rem; }
  .toc a { border: 1px solid var(--line); }
  .speed { margin-left: 0; width: 100%; }
  .speed input { flex: 1; width: auto; }
  .caption { font-size: 0.75rem; }
}
@media (max-width: 560px) {
  .top { gap: 0.5rem; padding: 0.25rem 0.5rem; flex-wrap: wrap; }
  .shortcuts-wrap { display: none; }
  .nav a { padding: 0.375rem 0.5rem; }
  .btn { padding: 0.375rem 0.625rem; }
  .btn-row { width: 100%; }
  .btn-row .btn { flex: 1; }
  .scroller { font-size: 16px; }
  .viewbar { gap: 0.25rem; padding: 0.25rem 0.5rem; }
  .btn.icon-btn { width: 40px; min-height: 40px; }
}
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
