const shape = await p.evaluate(() => { const l = (window as any).logomocja; return [typeof l.version, typeof l.run, typeof l.open]; });
ok(shape.join() === "string,function,function", "hook shape");
const r = await p.evaluate(() => (window as any).logomocja.run("np 10 pw 90 np 5", "2d"));
ok(r.segments.length === 2 && r.error === null, "hook run");
const o = await p.evaluate(() => (window as any).logomocja.open("kolor \"#c1763d\"\npowtorz 5 [np 180 pw 144]", "2d"));
ok(o.segments.length === 5, "hook open returns segments");
ok((await p.locator("textarea").inputValue()).includes("144"), "open fills the editor");
ok((await p.locator(".caption").innerText()).includes("Odcinków: 5"), "open drew on screen: " + (await p.locator(".caption").innerText()));

// 2 stepping
await p.evaluate(() => (window as any).logomocja.open("np 50\npw 90\nnp 50", "2d"));
await p.click("text=Reset");
await p.click("button:has-text('Krok')");
ok((await status(p)).includes("wiersz 2") || (await status(p)).includes("Wstrzymano"), "step status: " + (await status(p)));
ok(await p.locator(".overlay .l.exec").count() === 1, "executing line highlighted");
await p.keyboard.press("Control+.");
await p.keyboard.press("Control+.");
ok((await status(p)).includes("Zakończono"), "stepping finishes: " + (await status(p)));

// 3 error marker
await p.locator("textarea").fill("np 10\nskacz 5");
await p.waitForTimeout(900);
ok(await p.locator(".overlay .err").count() > 0, "live error squiggle");
ok((await status(p)).includes("wierszu 2, kolumnie 1"), "live error message: " + (await status(p)));
await p.click("button:has-text('Uruchom')");
await p.waitForTimeout(200);
ok((await status(p)).includes("Nieznane polecenie"), "run shows Polish parse error");
ok((await p.locator(".caption").innerText()).includes("Odcinków: 0"), "parse error draws nothing");
await p.locator("textarea").fill("np 10\nnp 1 / 0\nnp 5");
await p.click("button:has-text('Uruchom')");
await p.waitForTimeout(1500);
ok((await status(p)).includes("Dzielenie przez zero"), "run-time error: " + (await status(p)));
ok((await p.locator(".caption").innerText()).includes("Odcinków: 1"), "run-time error keeps strokes");

// animated run + pause/resume
await p.locator("textarea").fill("powtorz 200 [np 1 pw 5]");
await p.locator("#speed").fill("3");
await p.click("button:has-text('Uruchom')");
await p.waitForTimeout(400);
ok((await status(p)).includes("Działa"), "running: " + (await status(p)));
ok(await p.locator("textarea").evaluate((t: HTMLTextAreaElement) => t.readOnly), "editor locked while running");
await p.keyboard.press("Escape");
ok((await status(p)).includes("Wstrzymano"), "Esc pauses: " + (await status(p)));
const n1 = await p.locator(".caption").innerText();
await p.waitForTimeout(400);
ok(n1 === (await p.locator(".caption").innerText()), "paused stays still");
await p.screenshot({ path: "/tmp/shots/paused.png" });
await p.click("button:has-text('Wznów')");
await p.locator("#speed").fill("10");
await p.waitForTimeout(800);
ok((await status(p)).includes("Zakończono"), "resume finishes: " + (await status(p)));
await p.keyboard.press("Control+Shift+.");
ok((await p.locator(".caption").innerText()).includes("Odcinków: 0"), "reset shortcut");

// 5 examples + draft protection
await p.locator("textarea").fill("np 123 ; moje");
await p.click("role=tab[name='Przykłady']");
await p.click("button[aria-label^='Wczytaj przykład Gwiazda']");
ok(await p.locator(".bar.warn").isVisible(), "confirm bar shown for dirty draft");
ok((await p.locator("textarea").inputValue()) === "np 123 ; moje", "draft untouched until confirmed");
await p.click("button:has-text('Anuluj')");
ok(!(await p.locator(".bar.warn").isVisible()), "cancel hides bar");
await p.click("button[aria-label^='Wczytaj przykład Gwiazda']");
await p.click("button:has-text('Wczytaj i zastąp')");
ok((await p.locator("textarea").inputValue()).startsWith("; Sekret gwiazdy"), "example loaded after confirm");
ok(await p.locator("button:has-text('Przywróć poprzedni szkic')").isVisible(), "restore offered");
await p.click("button:has-text('Przywróć poprzedni szkic')");
ok((await p.locator("textarea").inputValue()) === "np 123 ; moje", "restore works");
// 3D example switches mode
await p.click("role=tab[name='Przykłady']");
await p.click("button[aria-label^='Wczytaj przykład Helisa']");
await p.click("button:has-text('Wczytaj i zastąp')").catch(() => {});
ok(await p.locator("#mode-3d").isChecked(), "3D example switched to 3D");
await p.screenshot({ path: "/tmp/shots/helisa.png" });

// persistence
await p.click("label[for=mode-2d]");
await p.locator("textarea").fill("np 77 ; trwałe");
await p.click("label[for=mode-3d]");
await p.locator("textarea").fill("gora 10 np 5 ; trzy-d");
await p.reload();
await p.waitForFunction(() => (window as any).logomocja);
ok((await p.locator("textarea").inputValue()).includes("trzy-d"), "3D draft survived reload");
await p.click("label[for=mode-2d]");
ok((await p.locator("textarea").inputValue()).includes("trwałe"), "2D draft survived reload");

// theme
const before = await p.evaluate(() => getComputedStyle(document.body).backgroundColor);
await p.click("button[aria-label^='Motyw']"); // -> light
await p.click("button[aria-label^='Motyw']"); // -> dark
const after = await p.evaluate(() => [document.documentElement.dataset.theme, getComputedStyle(document.body).backgroundColor, localStorage.getItem("logomocja:theme")]);
ok(after[0] === "dark" && after[1] !== before && after[2] === "dark", "theme toggle persisted " + after.join());

// challenges
await p.click("role=tab[name='Wyzwania']");
await p.click("button[aria-label*='Kwadrat o boku 100']");
ok(await p.locator(".challenge-bar").isVisible(), "challenge bar shown");
await p.locator("textarea").fill("powtorz 4 [np 90 pw 90]");
await p.click("button:has-text('Sprawdź rozwiązanie')");
ok((await p.locator(".verdict").innerText()).includes("Jeszcze nie"), "wrong answer fails: " + (await p.locator(".verdict").innerText()));
await p.screenshot({ path: "/tmp/shots/challenge-fail.png" });
await p.locator("textarea").fill("powtorz 4 [np 100 pw 90]");
await p.click("button:has-text('Sprawdź rozwiązanie')");
ok((await p.locator(".verdict").innerText()).includes("Zaliczone"), "right answer passes");
await p.reload();
await p.waitForFunction(() => (window as any).logomocja);
await p.click("role=tab[name='Wyzwania']");
ok((await p.locator("#panel-challenges").innerText()).includes("Rozwiązane: 1"), "progress persisted");

// share
await p.click("role=tab[name='Kod']");
await p.locator("textarea").fill("powtorz 3 [np 90 pw 120]");
await p.click("#share-btn");
const url = await p.locator("#share-url").inputValue();
ok(url.includes("#/u/2d/"), "permalink: " + url.slice(0, 80));
await p.click("button:has-text('Kopiuj link')");
ok((await p.locator(".share-note").innerText()).includes("Skopiowano"), "copy note");
const p2 = await newPage();
await p2.goto(url);
await p2.waitForTimeout(600);
ok((await p2.locator("textarea").inputValue()) === "powtorz 3 [np 90 pw 120]", "permalink loads program");
ok((await p2.locator(".caption").innerText()).includes("Odcinków: 3"), "permalink runs program");
ok(!p2.url().includes("#/u/"), "hash cleaned after load");
await p2.close();

// files
const [dl] = await Promise.all([p.waitForEvent("download"), p.click("button:has-text('Pobierz .logo')")]);
ok(dl.suggestedFilename() === "program-2d.logo", "download name " + dl.suggestedFilename());
const path = await dl.path();
ok(readFileSync(path!, "utf8") === "powtorz 3 [np 90 pw 120]", "download content");
writeFileSync("/tmp/in.logo", "﻿; z pliku\r\nnp 40\r\npw 90\r\nnp 40\r\n");
await p.setInputFiles("input[type=file]", "/tmp/in.logo");
await p.waitForTimeout(300);
ok(await p.locator(".bar.warn").isVisible(), "file open asks before replacing dirty draft");
await p.click("button:has-text('Wczytaj i zastąp')");
ok((await p.locator("textarea").inputValue()) === "; z pliku\nnp 40\npw 90\nnp 40\n", "file content normalised");
const [png] = await Promise.all([p.waitForEvent("download"), p.click("button[aria-label='Zapisz rysunek jako PNG']")]);
const pb = readFileSync((await png.path())!);
ok(pb.subarray(1, 4).toString() === "PNG" && pb.readUInt32BE(16) === 1600, "PNG 2D export " + pb.readUInt32BE(16) + "x" + pb.readUInt32BE(20));
await p.click("label[for=mode-3d]");
await p.evaluate(() => (window as any).logomocja.open("powtorz 4 [np 80 gora 90 np 20 dol 90]", "3d"));
const [png3] = await Promise.all([p.waitForEvent("download"), p.click("button[aria-label='Zapisz rysunek jako PNG']")]);
const pb3 = readFileSync((await png3.path())!);
ok(pb3.subarray(1, 4).toString() === "PNG", "PNG 3D export " + pb3.readUInt32BE(16) + "x" + pb3.readUInt32BE(20) + " bytes " + pb3.length);

// 3D orbit
const box = (await p.locator("canvas.stage").nth(1).boundingBox())!;
const s1 = await p.locator(".view-3d canvas").screenshot();
await p.mouse.move(box.x + 300, box.y + 300); await p.mouse.down(); await p.mouse.move(box.x + 420, box.y + 340, { steps: 5 }); await p.mouse.up();
await p.waitForTimeout(200);
const s2 = await p.locator(".view-3d canvas").screenshot();
ok(!s1.equals(s2), "3D orbit changes the picture");
await p.click("button[aria-label='Domyślny widok kamery']");
await p.waitForTimeout(200);
await p.screenshot({ path: "/tmp/shots/3d-view.png" });

// docs
await p.click("a:has-text('Dokumentacja')");
await p.waitForTimeout(300);
ok(await p.locator("h1:has-text('Dokumentacja języka')").isVisible(), "docs visible");
await p.screenshot({ path: "/tmp/shots/docs.png" });
await p.goto(base + "#/dokumentacja/cmd-pw");
await p.reload();
await p.waitForTimeout(500);
ok(await p.locator("#cmd-pw").isVisible(), "docs deep link after refresh");
await p.click("#cmd-pw button:has-text('Wypróbuj')");
await p.waitForTimeout(300);
ok(p.url().endsWith("#/") && (await p.locator("textarea").inputValue()).includes("pw 90"), "docs example opens in studio (" + (await p.locator(".bar.warn").isVisible()) + ")");

// a11y names
const unnamed = await p.evaluate(() => [...document.querySelectorAll("button, input, textarea, select, a")].filter((e: any) => { if (e.hidden || e.closest("[hidden]")) return false; const name = e.getAttribute("aria-label") || e.innerText?.trim() || (e.labels && e.labels[0]?.innerText) || e.getAttribute("title"); return !name; }).map((e: any) => e.outerHTML.slice(0, 80)));
ok(unnamed.length === 0, "all controls named " + JSON.stringify(unnamed));
await p.close();

// phone
const ph = await newPage({ viewport: { width: 390, height: 800 }, hasTouch: true, isMobile: true });
await ph.evaluate(() => (window as any).logomocja.open("powtorz 5 [np 180 pw 144]", "2d"));
await ph.screenshot({ path: "/tmp/shots/phone2.png" });
const overflow = await ph.evaluate(() => document.documentElement.scrollWidth > innerWidth);
ok(!overflow, "no horizontal page overflow on phone");
await ph.close();

// no WebGL
const b2 = await chromium.launch({ args: ["--disable-webgl", "--disable-3d-apis", "--disable-gpu"] });
const nog = await newPage({}, b2);
const hasGl = await nog.evaluate(() => !!document.createElement("canvas").getContext("webgl"));
console.log("webgl available in no-gl browser:", hasGl);
if (!hasGl) {
  await nog.click("label[for=mode-3d]");
  ok(await nog.locator(".notice3d").isVisible(), "3D off notice shown");
  await nog.click("label[for=mode-2d]");
  await nog.evaluate(() => (window as any).logomocja.open("np 50", "2d"));
  ok((await nog.locator(".caption").innerText()).includes("Odcinków: 1"), "2D still works without WebGL");
  await nog.click("label[for=mode-3d]");
  await nog.screenshot({ path: "/tmp/shots/nogl.png" });
}
await b2.close();
console.log("logs:", logs.join("\n") || "(none)");
console.log(fails ? `${fails} FAILED` : "ALL OK");
await b.close(); srv.stop(true);
