cat >> test/studio.test.ts <<'EOF'

describe("Studio: editing after an error", () => {
  test("a stale error marker is dropped when the text changes, the drawing stays", () => {
    const s = make();
    s.edit("np 5\nnp 1 / 0");
    s.runInstantly();
    expect(s.session.error).not.toBeNull();
    s.edit("np 5\nnp 1 / 2");
    expect(s.session.error).toBeNull();
    expect(s.session.segments.length).toBe(1);
    expect(s.stale).toBe(true);
  });
  test("after a parse error nothing is drawn and editing returns the session to idle", () => {
    const s = make();
    s.edit("skacz");
    s.runInstantly();
    expect(s.session.state).toBe("error");
    s.edit("np 1");
    expect(s.session.error).toBeNull();
    expect(s.session.state).toBe("idle");
  });
});
EOF
bun test test/studio.test.ts 2>&1 | grep -E "pass$|fail$|\(fail"

